/** 🧭️ Resolves an empty-facet marker only through a complete registered semantic owner chain. */
export function semanticArtifactEmptyFacetProjectionAuthority(facts: Readonly<{ sourcePath: string; sourceFileKindId: string }>, taxonomy: Taxonomy = loadTaxonomy()): Readonly<{ contractId: "artifact-empty-facet-primary-markdown-v1"; sourcePath: string; ownerForm?: string; destinationPath?: string; disposition: "project" | "unclaimed" }> {
  const contractId = "artifact-empty-facet-primary-markdown-v1" as const;
  const contract = taxonomy.semanticOwnedFileProjectionContracts[contractId];
  if (!contract || contract.contractKind !== "semantic-facet-primary-file") throw new Error("The artifact empty-facet primary-leaf contract is required.");
  const core = { contractId, sourcePath: facts.sourcePath };
  const kindId = taxonomy[contract.fileKindAuthority];
  const segments = facts.sourcePath.split("/");
  if (segments.some((segment) => !segment || segment === "." || segment === ".." || /[\\\0]/u.test(segment)) || !facts.sourcePath.startsWith(`${contract.sourceRoot}/`) || basename(facts.sourcePath) !== contract.sourceFilename || facts.sourceFileKindId !== kindId) return { ...core, disposition: "unclaimed" };
  const owners = dirname(facts.sourcePath).slice(contract.sourceRoot.length + 1).split("/");
  const matches = Object.entries(contract.ownerPathPatterns).filter(([, pattern]) => {
    const expected = pattern.split("/");
    if (expected.length !== owners.length) return false;
    let parentKindId = "plugins";
    return expected.every((segment, index) => {
      const name = owners[index]!;
      const kind = semanticDirectoryKindId(name, taxonomy, { parentKindId });
      if (!kind) return false;
      parentKindId = kind;
      const capture = /^\{([a-zA-Z]+)\}$/u.exec(segment)?.[1];
      if (!capture) return canonicalSemanticDirectoryName(name, taxonomy) === segment;
      const rule = contract.directoryCaptures[capture];
      return rule !== undefined && rule.kindIds.includes(kind) && (!rule.names || rule.names.includes(canonicalSemanticDirectoryName(name, taxonomy)));
    });
  });
  if (matches.length !== 1) return { ...core, disposition: "unclaimed" };
  return { ...core, ownerForm: matches[0]![0], destinationPath: `${dirname(facts.sourcePath)}/${canonicalFilenameForKind(kindId, taxonomy)}`, disposition: "project" };
}

/** 📚️ One exact physical scenario registration owned by a MutationCatalog vector. */
export interface SemanticProjectionScenarioRegistration {
  readonly id: string;
  readonly directoryName: string;
}

/** 🦠️ One independent physical vector registration; it is not a runtime-kind declaration. */
export interface SemanticProjectionVectorRegistration {
  readonly mutationId: string;
  readonly sourceMutationDirectoryName: string;
  readonly mutationDirectoryName: string;
  readonly scenarios: readonly SemanticProjectionScenarioRegistration[];
}

/** 📖️ One owner-local catalog whose physical and canonical vector identities are validated together. */
export interface SemanticProjectionCatalogRegistration {
  readonly ownerPath: string;
  readonly catalogId: string;
  readonly vectors: readonly SemanticProjectionVectorRegistration[];
}

/** 🧾️ Validates strict source/canonical identities, ownership, collisions, and path budgets. */
export function semanticProjectionCatalogProblems(registrations: readonly SemanticProjectionCatalogRegistration[], taxonomy: Taxonomy = loadTaxonomy()): string[] {
  const problems: string[] = [];
  const destinationOwners = new Set<string>();
  for (const [catalogIndex, catalog] of registrations.entries()) {
    const scope = `catalogs[${catalogIndex}]`;
    if (!catalog.ownerPath || !catalog.catalogId) problems.push(`${scope} must declare ownerPath and catalogId.`);
    const profile = catalog.ownerPath.match(/^(.*)\/🏅️standards\/🔖️([^/]+)\/🪆️subsets\/✳️([^/]+)$/u);
    if (!profile) problems.push(`${scope}.ownerPath is not an exact artifact standard/subset owner.`);
    const sourceTuples = new Set<string>();
    const canonicalTuples = new Set<string>();
    for (const [vectorIndex, vector] of catalog.vectors.entries()) {
      const vectorScope = `${scope}.vectors[${vectorIndex}]`;
      const keys = Object.keys(vector).sort().join("\0");
      if (keys !== ["mutationDirectoryName", "mutationId", "scenarios", "sourceMutationDirectoryName"].sort().join("\0")) problems.push(`${vectorScope} must contain exactly mutationId, sourceMutationDirectoryName, mutationDirectoryName, and scenarios.`);
      const mutationId = typeof vector.mutationId === "string" ? vector.mutationId : "";
      const sourceMutationDirectoryName = typeof vector.sourceMutationDirectoryName === "string" ? vector.sourceMutationDirectoryName : "";
      const mutationDirectoryName = typeof vector.mutationDirectoryName === "string" ? vector.mutationDirectoryName : "";
      for (const [field, value] of Object.entries({ mutationId, sourceMutationDirectoryName, mutationDirectoryName })) if (!value || value !== value.normalize("NFC") || /[\\/]/u.test(value)) problems.push(`${vectorScope}.${field} must be one non-empty NFC basename.`);
      if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/u.test(mutationId)) problems.push(`${vectorScope}.mutationId must be kebab-case.`);
      const sourceOwner = mutationCatalogSourceOwner(catalog.ownerPath, taxonomy);
      if (sourceOwner === null) problems.push(`${vectorScope} has invalid explicit catalog source ownership.`);
      const mutationRoot = `${sourceOwner ?? catalog.ownerPath}/🧬️schema/🧬️mutations`;
      const grouped = Object.hasOwn(taxonomy.mutationDomainOwners, mutationRoot);
      const registeredOwner = grouped ? mutationOwnerRelativePath(mutationRoot, mutationId, taxonomy) : null;
      const canonical = grouped ? registeredOwner ?? mutationDirectoryName : mutationDirectoryName;
      if (grouped) {
        if (!registeredOwner || registeredOwner.split("/").at(-1) !== sourceMutationDirectoryName || registeredOwner.split("/").at(-1) !== mutationDirectoryName) problems.push(`${vectorScope} has no exact registered domain-operation owner for mutationId.`);
      } else {
        if ((sourceMutationDirectoryName.match(/[a-z0-9][a-z0-9-]*$/u)?.[0] ?? "") !== mutationId) problems.push(`${vectorScope}.sourceMutationDirectoryName must render mutationId.`);
        if ((mutationDirectoryName.match(/[a-z0-9][a-z0-9-]*$/u)?.[0] ?? "") !== mutationId) problems.push(`${vectorScope}.mutationDirectoryName must render mutationId.`);
        for (const [field, name] of Object.entries({ sourceMutationDirectoryName, mutationDirectoryName })) if (leadingEmojiIdentity(name).rest === name || pathEmojiStatuteFindings([{ path: name, nodeKind: "directory" }], taxonomy.pathEmojiPolicy.genericEmojiIdentities).length > 0) problems.push(`${vectorScope}.${field} must be one canonical physical mutation identity.`);
      }
      if (!Array.isArray(vector.scenarios) || vector.scenarios.length === 0) problems.push(`${vectorScope}.scenarios must be non-empty.`);
      const scenarioIds = new Set<string>();
      const scenarioDirectories = new Set<string>();
      for (const [scenarioIndex, scenario] of (vector.scenarios ?? []).entries()) {
        const scenarioScope = `${vectorScope}.scenarios[${scenarioIndex}]`;
        if (Object.keys(scenario).sort().join("\0") !== ["directoryName", "id"].join("\0")) problems.push(`${scenarioScope} must contain exactly id and directoryName.`);
        const physicalScenarioId = leadingEmojiIdentity(scenario.directoryName).rest;
        if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/u.test(scenario.id)) problems.push(`${scenarioScope}.id must be one kebab-case logical identity.`);
        if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/u.test(physicalScenarioId) || physicalScenarioId === scenario.directoryName || scenario.directoryName !== scenario.directoryName.normalize("NFC") || /[\\/]/u.test(scenario.directoryName) || pathEmojiStatuteFindings([{ path: scenario.directoryName, nodeKind: "directory" }], taxonomy.pathEmojiPolicy.genericEmojiIdentities).length > 0) problems.push(`${scenarioScope}.directoryName must be one canonical NFC physical test-case identity.`);
        if (scenarioIds.has(scenario.id)) problems.push(`${scenarioScope}.id duplicates one logical scenario identity.`);
        scenarioIds.add(scenario.id);
        const scenarioDirectoryKey = scenario.directoryName.replaceAll("\uFE0F", "").toLocaleLowerCase("und");
        if (scenarioDirectories.has(scenarioDirectoryKey)) problems.push(`${scenarioScope}.directoryName duplicates one physical scenario identity.`);
        scenarioDirectories.add(scenarioDirectoryKey);
        const sourceTuple = `${mutationId}\0${sourceMutationDirectoryName}\0${scenario.id}`;
        const canonicalTuple = `${mutationId}\0${canonical}\0${scenario.id}`;
        if (sourceTuples.has(sourceTuple)) problems.push(`${scenarioScope} duplicates a source bundle tuple.`);
        if (canonicalTuples.has(canonicalTuple)) problems.push(`${scenarioScope} duplicates a canonical bundle tuple.`);
        sourceTuples.add(sourceTuple);
        canonicalTuples.add(canonicalTuple);
        if (profile) {
          const implementation = `${sourceOwner ?? catalog.ownerPath}/🧬️schema/🧬️mutations/${canonical}/🧪️tests/${scenario.directoryName}`.normalize("NFC");
          const fixture = `${sourceOwner ?? catalog.ownerPath}/🧫️fixtures/🧬️mutations/${canonical}/${scenario.directoryName}`.normalize("NFC");
          for (const destination of [implementation, fixture]) {
            const destinationKey = destination.replaceAll("\uFE0F", "").toLocaleLowerCase("und");
            if (destinationOwners.has(destinationKey)) problems.push(`${scenarioScope} collides at canonical pair root ${JSON.stringify(destination)}.`);
            destinationOwners.add(destinationKey);
          }
          const implementationReserve = taxonomy.semanticDescendantContracts[taxonomy.mutationCatalogProjection.implementationDescendantContractId]?.pathBudgetReserve.bytes ?? taxonomy.collisionPolicy.maxPathBytes;
          const fixtureReserve = taxonomy.semanticDescendantContracts[taxonomy.mutationCatalogProjection.fixtureDescendantContractId]?.pathBudgetReserve.bytes ?? taxonomy.collisionPolicy.maxPathBytes;
          if (new TextEncoder().encode(implementation).length + implementationReserve > taxonomy.collisionPolicy.maxPathBytes || new TextEncoder().encode(fixture).length + fixtureReserve > taxonomy.collisionPolicy.maxPathBytes) problems.push(`${scenarioScope} exceeds maxPathBytes after a canonical pair descendant reserve.`);
        }
      }
    }
  }
  return problems;
}

/** 🧭️ Full source-owner identity required before resolving a projected mutation member. */
export interface SemanticProjectedMemberContext {
  readonly projectionContractId: string;
  readonly artifactId: string;
  readonly artifactDirectoryName: string;
  readonly standardVersion: string;
  readonly standardDirectoryName: string;
  readonly subsetId: string;
  readonly subsetDirectoryName: string;
  readonly mutationId: string;
  readonly mutationDirectoryName: string;
  readonly scenarioId: string;
  readonly scenarioDirectoryName: string;
  readonly vectors: readonly SemanticProjectionVectorRegistration[];
}

function exactSemanticKindName(name: string, kindId: string, parentKindId: string, taxonomy: Taxonomy): boolean {
  return semanticDirectoryKindId(name, taxonomy, { parentKindId }) === kindId;
}

/** 🪞️ Resolves one canonical mutation member only from a complete artifact/subset/vector identity. */
export function semanticProjectedMemberKindId(name: string, context: SemanticProjectedMemberContext, taxonomy: Taxonomy = loadTaxonomy()): string | null {
  const pair = context.projectionContractId === taxonomy.mutationCatalogProjection.contractId ? taxonomy.mutationCatalogProjection : null;
  if (!pair || !context.artifactId || !context.mutationId || !context.scenarioId) return null;
  const sourceOwner = taxonomy.semanticDirectoryMemberKinds[pair.sourceOwnerKindId];
  if (!sourceOwner?.memberNames.includes(canonicalSemanticDirectoryName(context.artifactDirectoryName, taxonomy))) return null;
  if (context.standardDirectoryName !== `🔖️${context.standardVersion}` || !exactSemanticKindName(context.standardDirectoryName, "standard", "standards", taxonomy)) return null;
  if (context.subsetDirectoryName !== `✳️${context.subsetId}` || !exactSemanticKindName(context.subsetDirectoryName, "subset", "subsets", taxonomy)) return null;
  if (context.scenarioDirectoryName !== `🧪️${context.scenarioId}` || semanticDirectoryKindId(context.scenarioDirectoryName, taxonomy, { parentKindId: "mutation-test-subject" }) !== "test-case") return null;
  const memberName = canonicalSemanticDirectoryName(name, taxonomy);
  if (memberName !== canonicalSemanticDirectoryName(context.mutationDirectoryName, taxonomy)) return null;
  const vectorMatches = context.vectors.filter((vector) => vector.mutationId === context.mutationId && canonicalSemanticDirectoryName(vector.mutationDirectoryName, taxonomy) === memberName);
  if (vectorMatches.length !== 1) return null;
  const scenarioMatches = vectorMatches[0]!.scenarios.filter((scenario) => scenario.id === context.scenarioId && scenario.directoryName === context.scenarioDirectoryName);
  if (scenarioMatches.length !== 1) return null;
  const matches = Object.entries(taxonomy.semanticProjectedMemberKinds).filter(([id, spec]) => {
    if (spec.projectionContractId !== context.projectionContractId || !pair.fixtureSegments.some((segment) => "projectedMemberKindId" in segment && segment.projectedMemberKindId === id)) return false;
    const source = taxonomy.semanticDirectoryMemberKinds[spec.sourceMemberKindId];
    return spec.identityField === "mutationDirectoryName" && source?.memberNames.includes(memberName);
  });
  return matches.length === 1 ? matches[0]![0] : null;
}

/** 🪆️ Stable profile identity rendered only from captured standard/subset values. */
export interface SemanticProjectionProfileIdentity {
  readonly artifactId: string;
  readonly standardVersion: string;
  readonly subsetId: string;
}

/** 🎨️ Renders one profile without exposing a reverse string parser. */
export function renderSemanticProjectionProfile(contractId: string, identity: SemanticProjectionProfileIdentity, taxonomy: Taxonomy = loadTaxonomy()): string {
  const contract = taxonomy.semanticPathProjectionContracts[contractId];
  const renderer = contract && taxonomy.semanticPathProjectionProfileRenderers[contract.profileRendererId];
  if (!contract || !renderer || !identity.artifactId) throw new Error(`Unknown or incomplete semantic projection ${JSON.stringify(contractId)}.`);
  if (!new RegExp(taxonomy.semanticDirectoryKinds.standard.slugPattern, "u").test(identity.standardVersion) || !new RegExp(taxonomy.semanticDirectoryKinds.subset.slugPattern, "u").test(identity.subsetId)) throw new Error("Projection profile captures do not satisfy standard/subset slug contracts.");
  const rendered = renderer.template.replace("{standardVersion}", identity.standardVersion).replace("{subsetId}", identity.subsetId);
  const profileIndex = contract.destinationSegments.findIndex((segment) => "render" in segment && segment.render === "profile");
  const parent = profileIndex > 0 ? contract.destinationSegments[profileIndex - 1] : undefined;
  const parentKindId = parent && "kindId" in parent ? parent.kindId : undefined;
  if (semanticDirectoryKindId(rendered, taxonomy, { parentKindId }) !== renderer.directoryKindId) throw new Error(`Projection profile renderer produced invalid directory ${JSON.stringify(rendered)}.`);
  return rendered;
}

/** ⚖️ Renders profile tuples and rejects distinct tuples colliding within one artifact owner. */
export function renderSemanticProjectionProfiles(contractId: string, identities: readonly SemanticProjectionProfileIdentity[], taxonomy: Taxonomy = loadTaxonomy()): readonly Readonly<SemanticProjectionProfileIdentity & { directoryName: string }>[] {
  const seen = new Map<string, string>();
  return identities.map((identity) => {
    const directoryName = renderSemanticProjectionProfile(contractId, identity, taxonomy);
    const key = `${identity.artifactId}\0${directoryName}`;
    const tuple = `${identity.standardVersion}\0${identity.subsetId}`;
    const prior = seen.get(key);
    if (prior && prior !== tuple) throw new Error(`Projection profile collision for artifact ${JSON.stringify(identity.artifactId)} at ${JSON.stringify(directoryName)}.`);
    seen.set(key, tuple);
    return { ...identity, directoryName };
  });
}

/** 🔭️ Resolves exact schema-owned external projection consumers without owner inference. */
export function semanticPathProjectionReferenceConsumers(
  projectionContractId: string,
  sourcePath: string,
  adapter: SemanticPathProjectionReferenceConsumerContract["adapters"][number],
  form: SemanticPathProjectionReferenceConsumerForm,
  taxonomy: Taxonomy = loadTaxonomy(),
): readonly Readonly<{ id: string; contract: SemanticPathProjectionReferenceConsumerContract }>[] {
  return Object.entries(taxonomy.semanticPathProjectionReferenceConsumerContracts)
    .filter(([, contract]) => contract.projectionContractId === projectionContractId && contract.sourcePathIdentities.includes(sourcePath) && contract.adapters.includes(adapter) && contract.supportedForms.includes(form) && new RegExp(contract.sourcePathPattern, "u").test(sourcePath))
    .map(([id, contract]) => ({ id, contract }))
    .sort((left, right) => projectionByteCompare(left.id, right.id));
}

/** 🧱️ One exact source node supplied to the read-only projection authority. */
export interface SemanticProjectionAuthorityNode {
  readonly path: string;
  readonly nodeKind: "directory" | "file" | "symlink";
  readonly content?: string;
}

/** 🧭️ Inputs shared by the two artifact projection authorities. */
export interface SemanticPathProjectionAuthorityOptions {
  readonly artifactRoot: string;
  readonly contractId: string;
  readonly sourceRoot: string;
  readonly nodes: readonly SemanticProjectionAuthorityNode[];
  readonly occupiedPaths?: readonly string[];
  readonly layout?: "source" | "destination";
}

/** 🛤️ One deterministic existing-file projection pair. */
export interface SemanticPathProjectionMapping {
  readonly sourcePath: string;
  readonly destinationPath: string;
}

/** 📊️ Fail-closed projection result; mappings are exposed only when problems is empty. */
export interface SemanticPathProjectionAuthority {
  readonly contractId: string;
  readonly sourceRoot: string;
  readonly destinationRoot: string;
  readonly mappings: readonly SemanticPathProjectionMapping[];
  readonly destinationDirectoryCount: number;
  readonly destinationNodeCount: number;
  readonly mappingDigest: string;
  readonly maxPathBytes: number;
  readonly problems: readonly string[];
}

/** 🎨️ Shared forward-only root rendering result for artifact profile projections. */
export interface ArtifactPathProjectionRoot {
  readonly captures: Readonly<Record<string, string>>;
  readonly destinationRoot: string;
  readonly problems: readonly string[];
}

function projectionByteCompare(left: string, right: string): number {
  return Buffer.from(left).compare(Buffer.from(right));
}

function projectionDirectories(root: string, paths: readonly string[]): string[] {
  const directories = new Set<string>([root]);
  for (const path of paths) {
    const segments = path.slice(root.length + 1).split("/");
    segments.pop();
    let current = root;
    for (const segment of segments) {
      current = `${current}/${segment}`;
      directories.add(current);
    }
  }
  return [...directories].sort(projectionByteCompare);
}

function projectionCanonicalKey(path: string, comparison: "nfc" | "case-fold" | "vs16-fold"): string {
  const normalized = path.normalize("NFC");
  if (comparison === "nfc") return normalized;
  if (comparison === "case-fold") return normalized.toLocaleLowerCase("und");
  return normalized.replaceAll("\uFE0F", "");
}

function artifactProjectionPathProblems(paths: readonly Readonly<{ path: string; nodeKind: "directory" | "file" }>[], occupiedPaths: readonly string[], taxonomy: Taxonomy): string[] {
  const problems: string[] = [];
  for (const comparison of ["nfc", "case-fold", "vs16-fold"] as const) {
    const seen = new Map<string, string>();
    for (const entry of paths) {
      const key = `${entry.nodeKind}\0${projectionCanonicalKey(entry.path, comparison)}`;
      const prior = seen.get(key);
      if (prior && prior !== entry.path) problems.push(`${comparison} collision between ${JSON.stringify(prior)} and ${JSON.stringify(entry.path)}.`);
      seen.set(key, entry.path);
    }
  }
  const occupied = new Set(occupiedPaths.flatMap((path) => [path, projectionCanonicalKey(path, "nfc"), projectionCanonicalKey(path, "case-fold"), projectionCanonicalKey(path, "vs16-fold")]));
  for (const { path } of paths) {
    if ([path, projectionCanonicalKey(path, "nfc"), projectionCanonicalKey(path, "case-fold"), projectionCanonicalKey(path, "vs16-fold")].some((key) => occupied.has(key))) problems.push(`Projected destination ${JSON.stringify(path)} is occupied.`);
    if (new TextEncoder().encode(path).length > taxonomy.collisionPolicy.maxPathBytes) problems.push(`Projected destination ${JSON.stringify(path)} exceeds maxPathBytes ${taxonomy.collisionPolicy.maxPathBytes}.`);
  }
  return problems;
}

/** 🪆️ Parses exact source segments and renders a destination profile without reverse-splitting it. */
export function renderArtifactPathProjectionRoot(options: Pick<SemanticPathProjectionAuthorityOptions, "artifactRoot" | "contractId" | "sourceRoot">, taxonomy: Taxonomy = loadTaxonomy()): ArtifactPathProjectionRoot {
  const problems: string[] = [];
  const contract = taxonomy.semanticPathProjectionContracts[options.contractId];
  if (!contract || !contract.sourceArtifactMemberName) return { captures: {}, destinationRoot: "", problems: [`Unknown artifact projection contract ${JSON.stringify(options.contractId)}.`] };
  const sourceOwner = taxonomy.semanticDirectoryMemberKinds[contract.sourceOwnerKindId];
  const artifactDirectoryName = basename(options.artifactRoot);
  if (artifactDirectoryName !== contract.sourceArtifactMemberName || !sourceOwner?.memberNames.includes(artifactDirectoryName)) problems.push(`Artifact root does not match sourceArtifactMemberName ${JSON.stringify(contract.sourceArtifactMemberName)}.`);
  if (options.sourceRoot !== options.sourceRoot.normalize("NFC") || options.artifactRoot !== options.artifactRoot.normalize("NFC") || /\uFE0E/u.test(`${options.artifactRoot}\0${options.sourceRoot}`)) problems.push("Projection roots must be NFC and must not contain VS15.");
  const prefix = `${options.artifactRoot}/`;
  const sourceNames = options.sourceRoot.startsWith(prefix) ? options.sourceRoot.slice(prefix.length).split("/") : [];
  if (sourceNames.length !== contract.sourceSegments.length) problems.push("Source root does not have the exact projection grammar length.");
  const captures: Record<string, string> = {};
  let parentKindId: string | undefined;
  for (const [index, segment] of contract.sourceSegments.entries()) {
    const name = sourceNames[index] ?? "";
    if ("memberKindId" in segment) {
      const member = taxonomy.semanticDirectoryMemberKinds[segment.memberKindId];
      if (name !== segment.literal || !member?.ownerKindIds.includes(parentKindId ?? "") || !member.memberNames.includes(canonicalSemanticDirectoryName(name, taxonomy))) problems.push(`Source segment ${index} does not match exact member registry ${JSON.stringify(segment.memberKindId)}.`);
      parentKindId = segment.memberKindId;
      continue;
    }
    if ("projectedMemberKindId" in segment) {
      const projected = taxonomy.semanticProjectedMemberKinds[segment.projectedMemberKindId];
      const source = projected && taxonomy.semanticDirectoryMemberKinds[projected.sourceMemberKindId];
      const canonical = canonicalSemanticDirectoryName(name, taxonomy);
      if (!projected || projected.projectionContractId !== options.contractId || !projected.ownerKindIds.includes(parentKindId ?? "") || !source?.memberNames.includes(canonical) || canonical !== name) problems.push(`Source segment ${index} does not match projected member ${JSON.stringify(segment.projectedMemberKindId)}.`);
      captures[segment.capture] = name;
      parentKindId = segment.projectedMemberKindId;
      continue;
    }
    if ("literal" in segment) {
      if (name !== segment.literal || semanticDirectoryKindId(name, taxonomy, { parentKindId }) !== segment.kindId) problems.push(`Source segment ${index} does not match kind ${JSON.stringify(segment.kindId)}.`);
    } else {
      const kind = taxonomy.semanticDirectoryKinds[segment.kindId];
      if (!kind || semanticDirectoryKindId(name, taxonomy, { parentKindId }) !== segment.kindId || !name.startsWith(kind.emoji)) problems.push(`Source capture ${JSON.stringify(segment.capture)} does not match kind ${JSON.stringify(segment.kindId)}.`);
      else captures[segment.capture] = name.slice(kind.emoji.length);
    }
    parentKindId = segment.kindId;
  }
  const standardVersion = captures.standardVersion ?? "";
  const subsetId = captures.subsetId ?? "";
  let destinationParentKindId: string | undefined;
  const destinationNames: string[] = [];
  for (const segment of contract.destinationSegments) {
    if ("projectedMemberKindId" in segment) {
      const value = captures[segment.copy];
      if (!value) problems.push(`Destination copy ${JSON.stringify(segment.copy)} is missing.`);
      else destinationNames.push(value);
      destinationParentKindId = segment.projectedMemberKindId;
      continue;
    }
    if ("literal" in segment) destinationNames.push(segment.literal);
    else if ("render" in segment) {
      try {
        destinationNames.push(renderSemanticProjectionProfile(options.contractId, { artifactId: artifactDirectoryName, standardVersion, subsetId }, taxonomy));
      } catch (error) {
        problems.push(error instanceof Error ? error.message : String(error));
      }
    } else {
      const value = captures[segment.copy];
      if (!value) problems.push(`Destination copy ${JSON.stringify(segment.copy)} is missing.`);
      else destinationNames.push(value);
    }
    destinationParentKindId = segment.kindId;
  }
  return { captures, destinationRoot: problems.length === 0 ? `${options.artifactRoot}/${destinationNames.join("/")}` : "", problems };
}

/** 🗺️ Enumerates exact artifact roots by forward-rendering registered profile tuples. */
export function artifactPathProjectionCatalogRoots(artifactRoot: string, contractId: string, taxonomy: Taxonomy = loadTaxonomy()): readonly Readonly<{ sourceRoot: string; destinationRoot: string }>[] {
  const contract = taxonomy.semanticPathProjectionContracts[contractId];
  const catalog = contract && taxonomy.semanticPathProjectionCatalogContracts[contract.catalogContractId];
  if (!contract?.sourceArtifactMemberName || !catalog || !("contractKind" in catalog)) return [];
  const vectors = catalog.contractKind === "distributed-json-manifest-catalog" ? catalog.profileVectors : catalog.vectors;
  const roots = vectors.filter((vector) => vector.artifactId === basename(artifactRoot)).map((vector) => {
    const captures = vector as Readonly<Record<string, string>>;
    const sourceRoot = `${artifactRoot}/${contract.sourceSegments.map((segment) => "literal" in segment ? segment.literal : "projectedMemberKindId" in segment ? captures[segment.capture] : `${taxonomy.semanticDirectoryKinds[segment.kindId]?.emoji ?? ""}${captures[segment.capture] ?? ""}`).join("/")}`;
    const rendered = renderArtifactPathProjectionRoot({ artifactRoot, contractId, sourceRoot }, taxonomy);
    if (rendered.problems.length > 0) throw new Error(`Invalid forward profile vector for ${contractId}: ${rendered.problems.join(" | ")}`);
    return { sourceRoot, destinationRoot: rendered.destinationRoot };
  }).sort((left, right) => projectionByteCompare(left.destinationRoot, right.destinationRoot));
  for (const comparison of ["nfc", "case-fold", "vs16-fold"] as const) if (new Set(roots.map(({ destinationRoot }) => projectionCanonicalKey(destinationRoot, comparison))).size !== roots.length) throw new Error(`Forward profile vectors collide for ${contractId} under ${comparison}`);
  return roots;
}

function projectionJsonManifest(node: SemanticProjectionAuthorityNode, scope: string, problems: string[]): Record<string, unknown> | null {
  if (node.nodeKind !== "file" || typeof node.content !== "string") {
    problems.push(`${scope} must be a readable JSON file.`);
    return null;
  }
  try {
    const value = JSON.parse(node.content) as unknown;
    if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error("not an object");
    return value as Record<string, unknown>;
  } catch {
    problems.push(`${scope} must contain one JSON object.`);
    return null;
  }
}

function projectionFileMappingDigest(mappings: readonly SemanticPathProjectionMapping[]): string {
  return createHash("sha256").update(mappings.map(({ sourcePath, destinationPath }) => `${sourcePath}\0${destinationPath}`).join("\n")).digest("hex");
}

/** 🧾️ Validates and renders either the CAD manifest catalog or Draw exact command bundle without writes. */
export function semanticPathProjectionAuthority(options: SemanticPathProjectionAuthorityOptions, taxonomy: Taxonomy = loadTaxonomy()): SemanticPathProjectionAuthority {
  const root = renderArtifactPathProjectionRoot(options, taxonomy);
  const problems = [...root.problems];
  const contract = taxonomy.semanticPathProjectionContracts[options.contractId];
  const destinationLayout = options.layout === "destination";
  const physicalRoot = destinationLayout ? root.destinationRoot : options.sourceRoot;
  const pathOwners = new Map<string, SemanticProjectionAuthorityNode>();
  for (const node of options.nodes) {
    if (node.path !== node.path.normalize("NFC") || /\uFE0E/u.test(node.path)) problems.push(`Projection node ${JSON.stringify(node.path)} must be NFC and must not contain VS15.`);
    if (!(node.path === physicalRoot || node.path.startsWith(`${physicalRoot}/`))) problems.push(`Projection node ${JSON.stringify(node.path)} is outside its exact ${destinationLayout ? "destination" : "source"} root.`);
    if (pathOwners.has(node.path)) problems.push(`Projection node ${JSON.stringify(node.path)} is duplicated.`);
    pathOwners.set(node.path, node);
    if (node.nodeKind === "symlink") problems.push(`Projection source contains forbidden symlink ${JSON.stringify(node.path)}.`);
  }
  if (pathOwners.get(physicalRoot)?.nodeKind !== "directory") problems.push("Projection physical root must be present as a directory node.");
  const actualFiles = options.nodes.filter((node) => node.nodeKind === "file").map((node) => node.path).sort(projectionByteCompare);
  const expectedSourceDirectories = projectionDirectories(physicalRoot, actualFiles);
  const actualSourceDirectories = options.nodes.filter((node) => node.nodeKind === "directory").map((node) => node.path).sort(projectionByteCompare);
  if (expectedSourceDirectories.join("\0") !== actualSourceDirectories.join("\0")) problems.push("Projection source directories must be exactly those owned by source files.");
  const candidateMappings: SemanticPathProjectionMapping[] = [];
  if (contract && root.destinationRoot) {
    const catalog = taxonomy.semanticPathProjectionCatalogContracts[contract.catalogContractId];
    if (catalog && "contractKind" in catalog && catalog.contractKind === "distributed-json-manifest-catalog") {
      if (catalog.profileVectors.filter((vector) => vector.artifactId === basename(options.artifactRoot) && vector.standardVersion === root.captures.standardVersion && vector.subsetId === root.captures.subsetId).length !== 1) problems.push("CAD catalog must match exactly one forward owner profile vector.");
      const modelIds = new Set<string>();
      const memberIds = new Set<string>();
      const modelDirectories = actualSourceDirectories.filter((path) => dirname(path) === physicalRoot).map((path) => basename(path));
      if (modelDirectories.length === 0) problems.push("CAD catalog must contain at least one manifest-owned model.");
      for (const modelDirectoryName of modelDirectories) {
        const manifestPath = `${physicalRoot}/${modelDirectoryName}/${destinationLayout ? canonicalFilenameForKind("json", taxonomy) : catalog.modelManifestSourceFilename}`;
        const manifestNode = pathOwners.get(manifestPath);
        const manifest = manifestNode ? projectionJsonManifest(manifestNode, `Model manifest ${JSON.stringify(manifestPath)}`, problems) : null;
        if (!manifestNode) problems.push(`Model manifest is missing for ${JSON.stringify(modelDirectoryName)}.`);
        const leading = modelDirectoryName.match(/^(\p{Extended_Pictographic}\uFE0F?(?:\u200D\p{Extended_Pictographic}\uFE0F?)*)/u)?.[1] ?? "";
        const semanticStem = modelDirectoryName.slice(leading.length);
        if (!leading || canonicalSemanticDirectoryName(modelDirectoryName, taxonomy) !== modelDirectoryName || manifest?.schema !== catalog.modelManifestSchema || manifest?.[catalog.memberVersionField] !== catalog.requiredMemberVersion || manifest?.[catalog.modelIdentityField] !== semanticStem) problems.push(`Model manifest ${JSON.stringify(manifestPath)} must declare the canonical directory id, schema, and version.`);
        if (typeof manifest?.[catalog.modelIdentityField] === "string") {
          const id = manifest[catalog.modelIdentityField] as string;
          if (modelIds.has(id)) problems.push(`Model manifest identity ${JSON.stringify(id)} is duplicated.`);
          modelIds.add(id);
        }
      }
      for (const physicalPath of actualFiles) {
        const relativePath = physicalPath.slice(physicalRoot.length + 1);
        let segments = relativePath.split("/");
        if (destinationLayout) {
          if (segments.length === 2 && segments[1] === canonicalFilenameForKind("json", taxonomy)) segments = [segments[0]!, catalog.modelManifestSourceFilename];
          else {
            const rule = catalog.categoryRules.find((candidate) => candidate.sourceDirectoryName === segments[1]);
            if (segments.length !== 4 || segments[3] !== canonicalFilenameForKind("json", taxonomy) || !rule) problems.push(`Canonical CAD category member ${JSON.stringify(physicalPath)} does not match its exact category rule.`);
            else if (rule.sourceShape === "direct-semantic-json" && segments[2]!.startsWith(rule.memberDirectoryEmoji) && segments[2]!.length > rule.memberDirectoryEmoji.length) segments = [segments[0]!, segments[1]!, `🔣️${segments[2]!.slice(rule.memberDirectoryEmoji.length)}.json`];
            else if (rule.sourceShape === "nested-fixed-json") segments = [segments[0]!, segments[1]!, segments[2]!, rule.fixedSourceFilename];
            else problems.push(`Canonical CAD member ${JSON.stringify(physicalPath)} has no exact semantic directory identity.`);
          }
        }
        const sourcePath = `${options.sourceRoot}/${segments.join("/")}`;
        const modelDirectoryName = segments[0] ?? "";
        let destinationRelativePath = "";
        let expectedSchema = catalog.modelManifestSchema;
        if (segments.length === 2 && segments[1] === catalog.modelManifestSourceFilename) destinationRelativePath = `${modelDirectoryName}/${canonicalFilenameForKind("json", taxonomy)}`;
        else {
          const rule = catalog.categoryRules.find((candidate) => candidate.sourceDirectoryName === segments[1]);
          if (!rule) problems.push(`Unknown CAD catalog category in ${JSON.stringify(sourcePath)}.`);
          else if (rule.sourceShape === "direct-semantic-json" && segments.length === 3) {
            const match = segments[2]!.match(/^🔣️(.+)\.json$/u);
            if (!match) problems.push(`CAD direct category file ${JSON.stringify(sourcePath)} does not have the exact semantic JSON shape.`);
            else destinationRelativePath = `${modelDirectoryName}/${rule.sourceDirectoryName}/${rule.memberDirectoryEmoji}${match[1]}/${canonicalFilenameForKind("json", taxonomy)}`;
            expectedSchema = rule.manifestSchema;
          } else if (rule.sourceShape === "nested-fixed-json" && segments.length === 4 && segments[3] === rule.fixedSourceFilename && canonicalSemanticDirectoryName(segments[2]!, taxonomy) === segments[2]) {
            destinationRelativePath = `${modelDirectoryName}/${rule.sourceDirectoryName}/${segments[2]}/${canonicalFilenameForKind("json", taxonomy)}`;
            expectedSchema = rule.manifestSchema;
          } else problems.push(`CAD category member ${JSON.stringify(sourcePath)} does not match its exact category rule.`);
        }
        const node = pathOwners.get(physicalPath)!;
        const manifest = projectionJsonManifest(node, `Catalog manifest ${JSON.stringify(sourcePath)}`, problems);
        if (manifest && (manifest.schema !== expectedSchema || manifest[catalog.memberVersionField] !== catalog.requiredMemberVersion || typeof manifest[catalog.memberIdentityField] !== "string" || manifest[catalog.memberIdentityField] === "")) problems.push(`Catalog manifest ${JSON.stringify(sourcePath)} has an invalid manifest schema, identity, or version.`);
        if (manifest && typeof manifest[catalog.memberIdentityField] === "string") {
          const key = `${modelDirectoryName}\0${segments[1] ?? ""}\0${manifest[catalog.memberIdentityField]}`;
          if (memberIds.has(key)) problems.push(`Distributed catalog member identity ${JSON.stringify(key)} is duplicated.`);
          memberIds.add(key);
        }
        if (destinationRelativePath) {
          const destinationPath = `${root.destinationRoot}/${destinationRelativePath}`;
          if (destinationLayout && destinationPath !== physicalPath) problems.push(`Canonical CAD member ${JSON.stringify(physicalPath)} does not equal its forward-rendered catalog path.`);
          candidateMappings.push({ sourcePath, destinationPath });
        }
      }
    } else if (catalog && "contractKind" in catalog && catalog.contractKind === "exact-owner-vectors") {
      const capture = root.captures.commandDirectoryName;
      const vectors = catalog.vectors.filter((vector) => vector.artifactId === basename(options.artifactRoot) && vector.standardVersion === root.captures.standardVersion && vector.subsetId === root.captures.subsetId && vector.commandDirectoryName === capture);
      if (vectors.length !== 1) problems.push("Draw command source must match exactly one owner vector.");
      const descendant = taxonomy.semanticDescendantContracts[contract.descendantContractId];
      if (!descendant || "contractKind" in descendant) problems.push("Draw projection must reference one exact descendant bundle.");
      else {
        const expectedSourceNodes = new Set<string>();
        for (const node of descendant.requiredNodes) {
          const sourceParent = node.pathSegments.map((segment) => segment.literal);
          const destinationRelativePath = semanticDescendantNodeRelativePath(node, taxonomy);
          let sourceRelativePath = sourceParent.join("/");
          if (node.nodeType === "file") {
            sourceRelativePath = [...sourceParent, "kindId" in node ? node.sourceFilename ?? canonicalFilenameForKind(node.kindId, taxonomy) : fixedContractFilename(taxonomy.fixedFilenameContracts[node.fixedFilenameContractId]!)].join("/");
            candidateMappings.push({ sourcePath: `${options.sourceRoot}/${sourceRelativePath}`, destinationPath: `${root.destinationRoot}/${destinationRelativePath}` });
          }
          expectedSourceNodes.add(destinationLayout ? destinationRelativePath ? `${root.destinationRoot}/${destinationRelativePath}` : root.destinationRoot : sourceRelativePath ? `${options.sourceRoot}/${sourceRelativePath}` : options.sourceRoot);
        }
        if (destinationLayout) for (const directory of projectionDirectories(root.destinationRoot, candidateMappings.map(({ destinationPath }) => destinationPath))) expectedSourceNodes.add(directory);
        const actualSourceNodes = new Set(options.nodes.filter((node) => node.nodeKind !== "symlink").map((node) => node.path));
        if (expectedSourceNodes.size !== actualSourceNodes.size || [...expectedSourceNodes].some((path) => !actualSourceNodes.has(path))) problems.push("Draw source does not contain the exact command bundle.");
      }
    } else problems.push(`Projection catalog ${JSON.stringify(contract.catalogContractId)} has the wrong authority kind.`);
  }
  candidateMappings.sort((left, right) => projectionByteCompare(left.sourcePath, right.sourcePath));
  const destinationDirectories = root.destinationRoot ? projectionDirectories(root.destinationRoot, candidateMappings.map(({ destinationPath }) => destinationPath)) : [];
  const destinationNodes = [...destinationDirectories.map((path) => ({ path, nodeKind: "directory" as const })), ...candidateMappings.map(({ destinationPath: path }) => ({ path, nodeKind: "file" as const }))];
  problems.push(...artifactProjectionPathProblems(destinationNodes, options.occupiedPaths ?? [], taxonomy));
  const accepted = problems.length === 0;
  return {
    contractId: options.contractId,
    sourceRoot: options.sourceRoot,
    destinationRoot: root.destinationRoot,
    mappings: accepted ? candidateMappings : [],
    destinationDirectoryCount: accepted ? destinationDirectories.length : 0,
    destinationNodeCount: accepted ? destinationNodes.length : 0,
    mappingDigest: accepted ? projectionFileMappingDigest(candidateMappings) : "",
    maxPathBytes: accepted ? Math.max(0, ...destinationNodes.map(({ path }) => new TextEncoder().encode(path).length)) : 0,
    problems,
  };
}

/** 📏️ Derives a descendant node's canonical relative suffix from directory and physical file kinds. */
export function semanticDescendantNodeRelativePath(node: SemanticDescendantNode, taxonomy: Taxonomy = loadTaxonomy()): string {
  const parent = node.pathSegments.map((segment) => segment.literal);
  if (node.nodeType === "directory") return parent.join("/");
  if ("kindId" in node) return [...parent, canonicalPrimaryFilenameForKind(node.kindId, taxonomy)].join("/");
  const contract = taxonomy.fixedFilenameContracts[node.fixedFilenameContractId];
  if (!contract) throw new Error(`Unknown fixed filename contract ${JSON.stringify(node.fixedFilenameContractId)}.`);
  return [...parent, fixedContractFilename(contract)].join("/");
}

/** 🧭️ Context required to enforce a fixed contract's scope beyond its path pattern. */
export interface FixedContractMatchContext {
  readonly packageRoot?: boolean;
  readonly ecosystemId?: string;
  readonly parentDirectoryKindId?: string;
  readonly parentFixedDirectoryContractIds?: readonly string[];
  readonly siblingFixedFilenameContractIds?: readonly string[];
  readonly pathMatcher?: TaxonomyPathMatcher;
}

function taxonomyPatternExpression(pattern: string): RegExp {
  let expression = "^";
  for (let index = 0; index < pattern.length;) {
    if (pattern.slice(index, index + 3) === "**/") {
      expression += "(?:[^/]+/)*";
      index += 3;
      continue;
    }
    const character = pattern[index]!;
    if (character === "*" && pattern[index + 1] === "*") {
      expression += ".*";
      index += 2;
      continue;
    }
    if (character === "*") expression += "[^/]*";
    else if (character === "?") expression += "[^/]";
    else if (character === "[") {
      const end = pattern.indexOf("]", index + 1);
      if (end < 0) throw new Error(`Invalid taxonomy path pattern ${JSON.stringify(pattern)}.`);
      expression += pattern.slice(index, end + 1);
      index = end;
    } else expression += character.replace(/[\\^$.*+?()[\]{}|]/gu, "\\$&");
    index += 1;
  }
  return new RegExp(`${expression}$`, "u");
}

/** 🪢 Matches one NFC workspace-relative POSIX path against the v7 contract glob grammar. */
export function taxonomyPathPatternMatches(path: string, pattern: string): boolean {
  const normalizedPath = path.replaceAll("\\", "/").replace(/^\.\//u, "").normalize("NFC");
  return taxonomyPatternExpression(pattern.normalize("NFC")).test(normalizedPath);
}

/** 🧮️ An invocation-owned matcher with private compiled patterns and no retained path results. */
export interface TaxonomyPathMatcher {
  readonly matches: (path: string, pattern: string) => boolean;
}

/** 🧵️ Reuses successful pure compilations only for this validation or query invocation. */
export function createTaxonomyPathMatcher(): TaxonomyPathMatcher {
  const expressions = new Map<string, RegExp>();
  return Object.freeze({
    matches(path: string, pattern: string): boolean {
      const normalizedPath = path.replaceAll("\\", "/").replace(/^\.\//u, "").normalize("NFC");
      const normalizedPattern = pattern.normalize("NFC");
      let expression = expressions.get(normalizedPattern);
      if (!expression) {
        expression = taxonomyPatternExpression(normalizedPattern);
        expressions.set(normalizedPattern, expression);
      }
      return expression.test(normalizedPath);
    },
  });
}

/** 🔒️Parses a finite union of literal, separately declared parent-directory authorities. */
export function parseFixedDirectoryContractSetScope(input: unknown, parents: Readonly<Record<string, FixedDirectoryContract>>): Extract<FixedContractScope, { kind: "fixed-directory-contract-set" }> {
  if (!input || typeof input !== "object" || Array.isArray(input)) throw new Error("Fixed parent scope must be an object");
  const row = input as Record<string, unknown>;
  if (Object.keys(row).sort().join(",") !== "fixedDirectoryContractIds,kind" || row.kind !== "fixed-directory-contract-set" || !Array.isArray(row.fixedDirectoryContractIds) || row.fixedDirectoryContractIds.length < 1 || row.fixedDirectoryContractIds.length > 256) throw new Error("Fixed parent scope requires one nonempty finite parent ID set");
  const ids = new Set<string>(), paths = new Set<string>();
  for (const id of row.fixedDirectoryContractIds) {
    if (typeof id !== "string" || !id || ids.has(id) || !parents[id]) throw new Error("Fixed parent scope contains a duplicate or unknown directory contract ID");
    const parent = parents[id];
    if (/[*?\[\]{}]/u.test(parent.pathPattern) || !["exact-path", "path-pattern", "repository-root"].includes(parent.scope.kind) || paths.has(parent.pathPattern)) throw new Error("Fixed parent scope requires distinct literal parent authorities");
    ids.add(id);
    paths.add(parent.pathPattern);
  }
  return { kind: "fixed-directory-contract-set", fixedDirectoryContractIds: [...ids] };
}

/** 🏷️Resolves only a declared finite parent set, with no recursive aliases or inferred parents. */
export function parseNamedFixedDirectoryContractSetScope(input: unknown, parents: Readonly<Record<string, FixedDirectoryContract>>, sets: Readonly<Record<string, readonly string[]>>): Extract<FixedContractScope, { kind: "fixed-directory-contract-set" }> {
  if (!input || typeof input !== "object" || Array.isArray(input)) throw new Error("Named fixed parent scope must be an object");
  const row = input as Record<string, unknown>;
  if (Object.keys(row).sort().join(",") !== "fixedDirectoryContractSetId,kind" || row.kind !== "named-fixed-directory-contract-set" || typeof row.fixedDirectoryContractSetId !== "string" || !/^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/u.test(row.fixedDirectoryContractSetId) || !Object.hasOwn(sets, row.fixedDirectoryContractSetId)) throw new Error("Named fixed parent scope requires one declared set ID");
  return parseFixedDirectoryContractSetScope({ kind: "fixed-directory-contract-set", fixedDirectoryContractIds: sets[row.fixedDirectoryContractSetId] }, parents);
}

function fixedScopeMatches(contract: FixedFilenameContract | FixedDirectoryContract, path: string, context: FixedContractMatchContext, sets: Readonly<Record<string, readonly string[]>> = {}): boolean {
  if (contract.scope.kind === "exact-path") return path === contract.scope.path;
  if (contract.scope.kind === "repository-root") return !path.includes("/");
  if (contract.scope.kind === "package-root") return context.packageRoot === true && context.ecosystemId === contract.scope.ecosystemId;
  if (contract.scope.kind === "directory-kind") return context.parentDirectoryKindId === contract.scope.directoryKindId;
  if (contract.scope.kind === "fixed-directory-contract") return context.parentFixedDirectoryContractIds?.includes(contract.scope.fixedDirectoryContractId) === true;
  if (contract.scope.kind === "fixed-directory-contract-set") return contract.scope.fixedDirectoryContractIds.some((id) => context.parentFixedDirectoryContractIds?.includes(id));
  if (contract.scope.kind === "named-fixed-directory-contract-set") return sets[contract.scope.fixedDirectoryContractSetId]?.some((id) => context.parentFixedDirectoryContractIds?.includes(id)) === true;
  if (contract.scope.kind === "sibling-fixed-filename-contract") return context.siblingFixedFilenameContractIds?.includes(contract.scope.fixedFilenameContractId) === true;
  return true;
}

/** 📄️ Extracts the exact literal basename owned by a fixed filename contract. */
export function fixedContractFilename(contract: FixedFilenameContract): string {
  return contract.pathPattern.slice(contract.pathPattern.lastIndexOf("/") + 1);
}

/** 📏️ Comparable specificity tuple for deterministic fixed-contract precedence. */
export function fixedContractSpecificity(contract: FixedFilenameContract | FixedDirectoryContract): readonly [number, number, number, number] {
  const wildcardTokens = contract.pathPattern.match(/\*\*|\*|\?|\[[^\]]+\]/gu) ?? [];
  const literalSegments = contract.pathPattern.split("/").filter((segment) => !/\*|\?|\[/u.test(segment)).length;
  const literalCodePoints = [...contract.pathPattern.replace(/\*\*|\*|\?|\[[^\]]+\]|\//gu, "")].length;
  const scopeStrength = { "path-pattern": 0, "directory-kind": 1, "package-root": 2, "fixed-directory-contract": 3, "fixed-directory-contract-set": 3, "named-fixed-directory-contract-set": 3, "sibling-fixed-filename-contract": 3, "repository-root": 4, "exact-path": 5 }[contract.scope.kind];
  return [literalSegments, literalCodePoints, -wildcardTokens.length, scopeStrength];
}

function compareFixedContracts(left: readonly [string, FixedFilenameContract | FixedDirectoryContract], right: readonly [string, FixedFilenameContract | FixedDirectoryContract]): number {
  const leftScore = fixedContractSpecificity(left[1]);
  const rightScore = fixedContractSpecificity(right[1]);
  for (let index = 0; index < leftScore.length; index += 1) if (leftScore[index] !== rightScore[index]) return rightScore[index]! - leftScore[index]!;
  return left[0].localeCompare(right[0]);
}

function fixedContractWinner<T extends FixedFilenameContract | FixedDirectoryContract>(kind: "filename" | "directory", matches: readonly (readonly [string, T])[]): string[] {
  if (matches.length === 0) return [];
  const ordered = [...matches].sort(compareFixedContracts);
  if (ordered.length > 1 && fixedContractSpecificity(ordered[0]![1]).every((score, index) => score === fixedContractSpecificity(ordered[1]![1])[index])) {
    throw new Error(`Path resolves to equal-specificity fixed ${kind} contracts ${JSON.stringify(ordered[0]![0])} and ${JSON.stringify(ordered[1]![0])}.`);
  }
  return [ordered[0]![0]];
}

/** 🔒️ Resolves the single deterministic fixed filename winner. */
export function fixedFilenameContractIdsForPath(path: string, taxonomy: Taxonomy = loadTaxonomy(), context: FixedContractMatchContext = {}): string[] {
  const normalized = path.replaceAll("\\", "/").replace(/^\.\//u, "").normalize(taxonomy.unicodeNormalization.form);
  return fixedContractWinner("filename", Object.entries(taxonomy.fixedFilenameContracts)
    .filter(([, contract]) => (context.pathMatcher?.matches(normalized, contract.pathPattern) ?? taxonomyPathPatternMatches(normalized, contract.pathPattern)) && fixedScopeMatches(contract, normalized, context, taxonomy.fixedDirectoryContractSets)));
}

/** 📁️ Resolves the single deterministic fixed directory winner. */
export function fixedDirectoryContractIdsForPath(path: string, taxonomy: Taxonomy = loadTaxonomy(), context: FixedContractMatchContext = {}): string[] {
  const normalized = path.replaceAll("\\", "/").replace(/^\.\//u, "").replace(/\/$/u, "").normalize(taxonomy.unicodeNormalization.form);
  return fixedContractWinner("directory", Object.entries(taxonomy.fixedDirectoryContracts)
    .filter(([, contract]) => (context.pathMatcher?.matches(normalized, contract.pathPattern) ?? taxonomyPathPatternMatches(normalized, contract.pathPattern)) && fixedScopeMatches(contract, normalized, context, taxonomy.fixedDirectoryContractSets)));
}

/** 🧵️Invocation-owned fixed-contract resolver that indexes literal basenames and compiles each glob once. */
export function createFixedContractResolver(taxonomy: Taxonomy = loadTaxonomy()): Readonly<{
  filenameIdsForPath: (path: string, context?: FixedContractMatchContext) => string[];
  directoryIdsForPath: (path: string, context?: FixedContractMatchContext) => string[];
}> {
  const matcher = createTaxonomyPathMatcher();
  const index = <T extends FixedFilenameContract | FixedDirectoryContract>(contracts: Readonly<Record<string, T>>) => {
    const literal = new Map<string, (readonly [string, T])[]>(), wildcard: (readonly [string, T])[] = [];
    for (const entry of Object.entries(contracts)) {
      const name = entry[1].pathPattern.slice(entry[1].pathPattern.lastIndexOf("/") + 1);
      if (/[?*\[]/u.test(name)) wildcard.push(entry);
      else literal.set(name, [...(literal.get(name) ?? []), entry]);
    }
    return (path: string, context: FixedContractMatchContext, kind: "filename" | "directory"): string[] => {
      const normalized = path.replaceAll("\\", "/").replace(/^\.\//u, "").replace(kind === "directory" ? /\/$/u : /$^/u, "").normalize(taxonomy.unicodeNormalization.form);
      const name = normalized.slice(normalized.lastIndexOf("/") + 1);
      const candidates = [...(literal.get(name) ?? []), ...wildcard];
      return fixedContractWinner(kind, candidates.filter(([, contract]) => matcher.matches(normalized, contract.pathPattern) && fixedScopeMatches(contract, normalized, context, taxonomy.fixedDirectoryContractSets)));
    };
  };
  const filenames = index(taxonomy.fixedFilenameContracts), directories = index(taxonomy.fixedDirectoryContracts);
  return Object.freeze({
    filenameIdsForPath: (path: string, context: FixedContractMatchContext = {}) => filenames(path, context, "filename"),
    directoryIdsForPath: (path: string, context: FixedContractMatchContext = {}) => directories(path, context, "directory"),
  });
}

/** 🚫️ Resolves an exact fixed-looking path to its schema-owned normalize/relocate decision. */
export function fixedFilenameRejectionContractIdForPath(path: string, taxonomy: Taxonomy = loadTaxonomy()): string | null {
  const normalized = path.replaceAll("\\", "/").replace(/^\.\//u, "").normalize(taxonomy.unicodeNormalization.form);
  const matches = Object.entries(taxonomy.fixedFilenameRejectionContracts).filter(([, contract]) => contract.sourcePathIdentities.includes(normalized));
  if (matches.length > 1) throw new Error(`Path resolves to multiple fixed filename rejection contracts: ${matches.map(([id]) => id).join(", ")}.`);
  return matches[0]?.[0] ?? null;
}

function exactContractFilename(contractId: string | null, taxonomy: Taxonomy): string | null {
  if (!contractId) return null;
  const fixed = taxonomy.fixedFilenameContracts[contractId];
  return fixed ? fixedContractFilename(fixed) : taxonomy.configurableEntryContracts[contractId]?.filename ?? null;
}

function componentFilenames(taxonomy: Taxonomy): string[] {
  return [...new Set(Object.values(taxonomy.componentFileKinds).flatMap((kindId) => canonicalFilenamesForKind(kindId, taxonomy)))];
}

/**
 * 🧬️ Resolves a schema facet's DECLARED kind: a kind claims a facet module by listing it in
 * `schemaFacetKinds[<kind>].facetPathIdentities`, everything else is `schemaDefaultFacetKind`. Nothing is
 * probed from disk, so a half-authored module never silently changes the formats it owes.
 */
export function resolveSchemaFacetKind(facetRel: string, taxonomy: Taxonomy = loadTaxonomy()): string {
  const normalized = facetRel.replaceAll("\\", "/").replace(/^\.\//u, "").replace(/\/+$/u, "").normalize("NFC");
  for (const [kindId, kind] of Object.entries(taxonomy.schemaFacetKinds ?? {})) if (kind.facetPathIdentities.includes(normalized)) return kindId;
  return taxonomy.schemaDefaultFacetKind;
}

/** 📜️ Returns the schemaFormats entries required for one facet path (declared-kind subset). */
export function schemaFacetFormatEntries(facetRel: string, taxonomy: Taxonomy = loadTaxonomy()): [string, SchemaFormatSpec][] {
  const kind = taxonomy.schemaFacetKinds?.[resolveSchemaFacetKind(facetRel, taxonomy)];
  if (!kind) return Object.entries(taxonomy.schemaFormats ?? {}) as [string, SchemaFormatSpec][];
  return kind.formats
    .map((formatId) => [formatId, taxonomy.schemaFormats[formatId]] as [string, SchemaFormatSpec | undefined])
    .filter((entry): entry is [string, SchemaFormatSpec] => entry[1] !== undefined);
}

//#region 🧬️SchemaScopeCatalog
/** 🧾️ One machine-readable finding of the schema scope tooling; `code` is stable, `path` repository-relative. */
export interface SchemaScopeDiagnostic {
  readonly code: string;
  readonly path: string;
  readonly detail: string;
}

/** 🔗️ One `$ref` occurrence, already classified against the catalog addressing rules. */
export interface SchemaScopeReference {
  readonly documentPath: string;
  readonly pointer: string;
  readonly ref: string;
  readonly targetScopeId: string | null;
  readonly targetExportId: string | null;
  readonly local: boolean;
}

/** 📄️ One JSON Schema document inside a schema module. */
export interface SchemaScopeDocument {
  readonly path: string;
  readonly scopeId: string | null;
  /** 🧩️ Segments of the `$id` before its facet filename; a facet document repeats its module's scope path and only appends facet segments. */
  readonly scopePath: readonly string[] | null;
  readonly id: string | null;
  /** 🏷️ Filename of the `$id` without its `.json` suffix; the facet this document carries within its module. */
  readonly facetFilename: string | null;
  readonly dialect: string | null;
  readonly exports: readonly string[];
  /** 🗂️ Export id to the format ids its `x-semio-formats` annotation restricts it to; absent means every provided format. */
  readonly exportFormats: Readonly<Record<string, readonly string[]>>;
  readonly references: readonly SchemaScopeReference[];
}

/** 🧬️ One `🧬️schema` module on disk together with the owner level that admits it. */
export interface SchemaScopeModule {
  readonly modulePath: string;
  readonly ownerPath: string;
  readonly level: string | null;
  readonly facetKindId: string;
  readonly scopeId: string | null;
  readonly formats: Readonly<Record<string, string>>;
  readonly documents: readonly SchemaScopeDocument[];
  readonly hashes: Readonly<Record<string, string>>;
}

/** 🏷️ Where one export is declared: the module-relative file that carries it and the facet that file is. */
export interface SchemaCatalogExport {
  /** 🗂️ Module-relative path including every nested facet directory (`🔺️diff/📝️text/🔣️.json`); join with the scope `path`. */
  readonly file: string;
  /** 🏷️ Facet id derived from the declaring document's `$id` (`schema`, `snapshot`, `snapshot/text`, …). */
  readonly facet: string;
}

/** 📇️ The generated scope catalog: one row per scope id, derived only from declared `$id`s. */
export interface SchemaCatalogScope {
  readonly path: string;
  readonly level: string;
  readonly facetKind: string;
  /** 🗂️ Format id to module-relative leaf filename; join with `path` for the repository-relative source. */
  readonly formats: Readonly<Record<string, string>>;
  readonly exports: Readonly<Record<string, SchemaCatalogExport>>;
  readonly dependsOn: readonly string[];
  readonly hashes: Readonly<Record<string, string>>;
}

/** 📇️ Provenance header plus the deterministic scope table. */
export interface SchemaCatalog {
  readonly contractId: string;
  readonly catalogVersion: 1;
  readonly generator: string;
  readonly taxonomySchemaVersion: number;
  readonly jsonSchemaDialect: string;
  readonly scopes: Readonly<Record<string, SchemaCatalogScope>>;
}

/** 🧾️ Everything one repository walk produced: modules, catalog and every finding. */
export interface SchemaScopeInventory {
  readonly modules: readonly SchemaScopeModule[];
  readonly catalog: SchemaCatalog;
  readonly diagnostics: readonly SchemaScopeDiagnostic[];
  readonly placement: readonly SchemaScopeDiagnostic[];
}

function byteSort(left: string, right: string): number {
  return Buffer.from(left).compare(Buffer.from(right));
}

/** 🧮️ Validates the schema scope-owner, export-resolution and dialect vocabulary families. */
function validateSchemaScopeVocabulary(taxonomy: Taxonomy): string[] {
  const problems: string[] = [];
  const dialect = taxonomy.mutationPayloadSchemaAuthority?.jsonSchemaDialect;
  if (typeof taxonomy.schemaJsonDialect !== "string" || taxonomy.schemaJsonDialect !== dialect) problems.push("schemaJsonDialect must be the single dialect mutationPayloadSchemaAuthority already declares.");
  const levels = taxonomy.schemaScopeOwnerLevels;
  if (!levels || typeof levels !== "object") problems.push("schemaScopeOwnerLevels must declare the eligible schema scope-owner levels.");
  else {
    if (levels.facetDirName !== "🧬️schema" || semanticDirectoryKindId(levels.facetDirName, taxonomy) !== levels.directoryKindId) problems.push("schemaScopeOwnerLevels must bind the registered 🧬️schema directory kind.");
    if (typeof taxonomy.schemaDefaultFacetKind !== "string" || !taxonomy.schemaFacetKinds?.[taxonomy.schemaDefaultFacetKind]) problems.push("schemaDefaultFacetKind must name a declared schemaFacetKinds entry.");
    else if ((taxonomy.schemaFacetKinds[taxonomy.schemaDefaultFacetKind]?.facetPathIdentities ?? []).length !== 0) problems.push("schemaDefaultFacetKind must not claim exact facet modules; it is the fallback kind.");
    if (!levels.levels || typeof levels.levels !== "object" || Object.keys(levels.levels).length === 0) problems.push("schemaScopeOwnerLevels.levels must be a non-empty object.");
    else for (const [levelId, level] of Object.entries(levels.levels)) {
      if (!/^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/u.test(levelId)) problems.push(`schemaScopeOwnerLevels.levels[${JSON.stringify(levelId)}] must be a kebab identifier.`);
      if (!Array.isArray(level.pathPatterns) || level.pathPatterns.length === 0 || level.pathPatterns.some((value) => typeof value !== "string" || !value)) problems.push(`schemaScopeOwnerLevels.levels[${JSON.stringify(levelId)}].pathPatterns must be a non-empty string array.`);
      else for (const value of level.pathPatterns) try { void taxonomyPathPatternMatches("", value); } catch { problems.push(`schemaScopeOwnerLevels.levels[${JSON.stringify(levelId)}] has an invalid path pattern ${JSON.stringify(value)}.`); }
      if (typeof level.reason !== "string" || level.reason.length < 16) problems.push(`schemaScopeOwnerLevels.levels[${JSON.stringify(levelId)}].reason must state why the level owns contracts.`);
    }
    if (!Array.isArray(levels.excludedOwnerPathPatterns) || levels.excludedOwnerPathPatterns.length === 0) problems.push("schemaScopeOwnerLevels.excludedOwnerPathPatterns must list the never-eligible owner shapes.");
    else for (const value of levels.excludedOwnerPathPatterns) try { void taxonomyPathPatternMatches("", value); } catch { problems.push(`schemaScopeOwnerLevels.excludedOwnerPathPatterns has an invalid path pattern ${JSON.stringify(value)}.`); }
    if (!Array.isArray(levels.fixtureOwnerPathPatterns) || levels.fixtureOwnerPathPatterns.length === 0) problems.push("schemaScopeOwnerLevels.fixtureOwnerPathPatterns must list the test and fixture collection roots.");
    else for (const value of levels.fixtureOwnerPathPatterns) try { void taxonomyPathPatternMatches("", value); } catch { problems.push(`schemaScopeOwnerLevels.fixtureOwnerPathPatterns has an invalid path pattern ${JSON.stringify(value)}.`); }
    if (Array.isArray(levels.fixtureOwnerPathPatterns) && Array.isArray(levels.excludedOwnerPathPatterns) && levels.fixtureOwnerPathPatterns.some((value) => levels.excludedOwnerPathPatterns.includes(value))) problems.push("schemaScopeOwnerLevels.fixtureOwnerPathPatterns and excludedOwnerPathPatterns must be disjoint: a collection is recognized by its own ancestors with the module-member carve-out, an excluded owner shape by an exact pattern.");
    if (typeof levels.fixtureOwnerReason !== "string" || levels.fixtureOwnerReason.length < 16) problems.push("schemaScopeOwnerLevels.fixtureOwnerReason must state why a collection is never a scope owner and why the schema documents inside it are findings.");
    if (typeof levels.moduleMemberDirName !== "string" || !(taxonomy.pluginChildDirs ?? []).includes(levels.moduleMemberDirName)) problems.push("schemaScopeOwnerLevels.moduleMemberDirName must be the declared module-member directory a collection pattern never claims.");
    if (typeof levels.mutationsFacetDirName !== "string" || !(taxonomy.schemaChildDirs ?? []).includes(levels.mutationsFacetDirName)) problems.push("schemaScopeOwnerLevels.mutationsFacetDirName must be a declared schema child directory.");
    if (typeof levels.inertSchemaDataKeyword !== "string" || !/^[a-z][A-Za-z0-9]*$/u.test(levels.inertSchemaDataKeyword)) problems.push("schemaScopeOwnerLevels.inertSchemaDataKeyword must name the case-file key that declares schema-shaped test inputs.");
  }
  const resolution = taxonomy.schemaExportResolution;
  if (!resolution || typeof resolution !== "object") problems.push("schemaExportResolution must declare how a consumer names one schema export.");
  else {
    const expected = ["catalogContractId", "catalogDocumentPath", "catalogPath", "exportIdPattern", "exportsKeyword", "forbiddenPlacementPatterns", "formatIds", "generator", "idBase", "idFacetFilenamePattern", "mutationAggregateFacetFilename", "mutationLeafFacetFilename", "mutationScopeSegment", "placementExceptions", "rootExportKeyword", "rustEntriesContractId", "scopeIdPattern", "scopeIdSeparator", "uriPattern", "uriScheme"];
    if (Object.keys(resolution).sort().join("\0") !== expected.join("\0")) problems.push(`schemaExportResolution must declare exactly ${expected.join(", ")}.`);
    if (resolution.uriScheme !== "schema" || !resolution.uriPattern.includes(`${resolution.uriScheme}://`)) problems.push("schemaExportResolution.uriPattern must bind its own declared scheme.");
    for (const [key, value] of [["uriPattern", resolution.uriPattern], ["idFacetFilenamePattern", resolution.idFacetFilenamePattern], ["scopeIdPattern", resolution.scopeIdPattern], ["exportIdPattern", resolution.exportIdPattern]] as const) {
      try { void new RegExp(value, "u"); } catch { problems.push(`schemaExportResolution.${key} is not a valid Unicode regular expression.`); }
    }
    if (typeof resolution.idBase !== "string" || !resolution.idBase.startsWith("https://") || !resolution.idBase.endsWith("/")) problems.push("schemaExportResolution.idBase must be an absolute https prefix ending in a separator.");
    if (resolution.scopeIdSeparator !== ".") problems.push("schemaExportResolution.scopeIdSeparator must be the dotted separator the descriptor ids already use.");
    if (resolution.rootExportKeyword !== "title" || resolution.exportsKeyword !== "$defs") problems.push("schemaExportResolution must read exports from the JSON Schema title and $defs keywords.");
    if (typeof resolution.catalogPath !== "string" || !resolution.catalogPath.endsWith(".json") || typeof resolution.catalogDocumentPath !== "string" || !resolution.catalogDocumentPath.endsWith(".md")) problems.push("schemaExportResolution must point at one generated JSON catalog and one generated Markdown index.");
    if (typeof resolution.generator !== "string" || !resolution.generator.includes("📜️script.ts schema generate")) problems.push("schemaExportResolution.generator must name the exact generating command.");
    if (!Array.isArray(resolution.forbiddenPlacementPatterns) || resolution.forbiddenPlacementPatterns.length === 0) problems.push("schemaExportResolution.forbiddenPlacementPatterns must list the retired schema placements.");
    if (!resolution.placementExceptions || typeof resolution.placementExceptions !== "object" || Array.isArray(resolution.placementExceptions)) problems.push("schemaExportResolution.placementExceptions must be an object of exact path to reason.");
    else for (const [path, reason] of Object.entries(resolution.placementExceptions)) if (typeof reason !== "string" || reason.length < 16 || path.split("/").some((segment) => !segment || segment === "." || segment === "..")) problems.push(`schemaExportResolution.placementExceptions[${JSON.stringify(path)}] must name an exact path and a stated reason.`);
    const dataFormats = [...(taxonomy.schemaFacetKinds?.[taxonomy.schemaDefaultFacetKind]?.formats ?? [])].sort();
    if (!resolution.formatIds || typeof resolution.formatIds !== "object" || Array.isArray(resolution.formatIds)) problems.push("schemaExportResolution.formatIds must map every default-facet-kind format key to its ascii format id.");
    else {
      if (Object.keys(resolution.formatIds).sort().join("\0") !== dataFormats.join("\0")) problems.push(`schemaExportResolution.formatIds must name exactly the ${taxonomy.schemaDefaultFacetKind} formats ${dataFormats.join(", ")}.`);
      const ids = Object.values(resolution.formatIds);
      if (ids.some((value) => typeof value !== "string" || !/^[a-z][a-z0-9]*$/u.test(value)) || new Set(ids).size !== ids.length) problems.push("schemaExportResolution.formatIds values must be unique lowercase ascii format ids.");
    }
    if (typeof resolution.rustEntriesContractId !== "string" || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/u.test(resolution.rustEntriesContractId)) problems.push("schemaExportResolution.rustEntriesContractId must be the kebab contract id of the Rust registry entry dump.");
    if (typeof resolution.mutationScopeSegment !== "string" || !new RegExp(resolution.scopeIdPattern, "u").test(resolution.mutationScopeSegment)) problems.push("schemaExportResolution.mutationScopeSegment must be one scope-id segment.");
    if (typeof resolution.mutationLeafFacetFilename !== "string" || !new RegExp(resolution.idFacetFilenamePattern, "u").test(resolution.mutationLeafFacetFilename)) problems.push("schemaExportResolution.mutationLeafFacetFilename must be a declared facet filename.");
    if (typeof resolution.mutationAggregateFacetFilename !== "string" || !new RegExp(resolution.idFacetFilenamePattern, "u").test(resolution.mutationAggregateFacetFilename)) problems.push("schemaExportResolution.mutationAggregateFacetFilename must be a declared facet filename.");
  }
  return problems;
}

/**
 * 🧫️ Whether a repository-relative path lies inside a test or fixture COLLECTION.
 *
 * Only the authored fixture and test self patterns name a collection root; every ancestor of the path is tested against
 * them, so the `/**` siblings would only restate the walk. The one carve-out is `🔨️modules/<m>`: a module
 * member is a module whatever emoji its name starts with, and without it the repository test platform
 * (`🔨️modules/🧪️test`, which owns the test-protocol contract every host reads) would be classified as a
 * collection of its own examples. A collection never owns a contract scope — and, since WP2c, a schema
 * contract facet inside one is always a `schema-fixture-defines-schema` finding. A case may declare
 * ordinary schema-shaped parser input as `inertSchemaData`, which never authorizes a contract facet.
 */
export function schemaScopeCollectionPath(path: string, taxonomy: Taxonomy = loadTaxonomy(), matcher: TaxonomyPathMatcher = createTaxonomyPathMatcher()): boolean {
  const levels = taxonomy.schemaScopeOwnerLevels;
  const roots = levels.fixtureOwnerPathPatterns.filter((pattern) => !pattern.endsWith("/**"));
  const segments = path.split("/");
  for (let index = 0; index < segments.length; index += 1) {
    if (index > 0 && segments[index - 1] === levels.moduleMemberDirName) continue;
    const prefix = segments.slice(0, index + 1).join("/");
    if (roots.some((pattern) => matcher.matches(prefix, pattern))) return true;
  }
  return false;
}

/** 🧱️ A contract facet below a collection boundary cannot become inert example data. */
export function schemaCollectionContractPath(path: string, taxonomy: Taxonomy = loadTaxonomy(), matcher: TaxonomyPathMatcher = createTaxonomyPathMatcher()): boolean {
  const segments = path.split("/");
  return segments.some((segment, index) => (segment === taxonomy.schemaScopeOwnerLevels.facetDirName || segment === "🛂️schema") && schemaScopeCollectionPath(segments.slice(0, index).join("/"), taxonomy, matcher));
}

/** 🚫️ Owner shapes that can never carry a schema module, regardless of the level patterns. */
export function schemaScopeOwnerExcluded(ownerPath: string, taxonomy: Taxonomy = loadTaxonomy(), matcher: TaxonomyPathMatcher = createTaxonomyPathMatcher()): boolean {
  return taxonomy.schemaScopeOwnerLevels.excludedOwnerPathPatterns.some((pattern) => matcher.matches(ownerPath, pattern)) || schemaScopeCollectionPath(ownerPath, taxonomy, matcher);
}

/** 🧭️ The declared owner level a schema module sits at, or `null` when no level admits it. */
export function schemaScopeOwnerLevel(ownerPath: string, taxonomy: Taxonomy = loadTaxonomy(), matcher: TaxonomyPathMatcher = createTaxonomyPathMatcher()): string | null {
  if (schemaScopeOwnerExcluded(ownerPath, taxonomy, matcher)) return null;
  for (const [levelId, level] of Object.entries(taxonomy.schemaScopeOwnerLevels.levels)) if (level.pathPatterns.some((pattern) => matcher.matches(ownerPath, pattern))) return levelId;
  return null;
}

/**
 * 🪞️ The owner directory a schema module belongs to: its parent, except when the module directory is
 * itself a declared owner level.
 *
 * `🧰️framework/🔨️modules/🧬️schema` is the framework module whose own name is the facet directory name, so
 * its parent is the module container `🧰️framework/🔨️modules`, which is deliberately not an owner level.
 * A module that already sits at an eligible level owns itself; the alternative — admitting the container —
 * would make every framework module's parent an owner.
 */
export function schemaScopeModuleOwnerPath(modulePath: string, taxonomy: Taxonomy = loadTaxonomy(), matcher: TaxonomyPathMatcher = createTaxonomyPathMatcher()): string {
  const parent = modulePath.slice(0, Math.max(0, modulePath.lastIndexOf("/")));
  if (schemaScopeOwnerLevel(parent, taxonomy, matcher)) return parent;
  return schemaScopeOwnerLevel(modulePath, taxonomy, matcher) ? modulePath : parent;
}

/** 🧩️ Splits one document `$id` into its scope path segments and its facet filename, or `null` when it is not addressable. */
export function schemaDocumentIdParts(documentId: string, taxonomy: Taxonomy = loadTaxonomy()): { readonly scopePath: readonly string[]; readonly facet: string } | null {
  const resolution = taxonomy.schemaExportResolution;
  if (!documentId.startsWith(resolution.idBase)) return null;
  const segments = documentId.slice(resolution.idBase.length).split("/");
  const facet = segments.pop();
  if (!facet || !new RegExp(resolution.idFacetFilenamePattern, "u").test(facet) || segments.length === 0) return null;
  return new RegExp(resolution.scopeIdPattern, "u").test(segments.join(resolution.scopeIdSeparator)) ? { scopePath: segments, facet } : null;
}

/** 🆔️ Derives the dotted scope id from one document `$id`; never from the path the file happens to sit at. */
export function schemaScopeIdFromDocumentId(documentId: string, taxonomy: Taxonomy = loadTaxonomy()): string | null {
  const parts = schemaDocumentIdParts(documentId, taxonomy);
  return parts ? parts.scopePath.join(taxonomy.schemaExportResolution.scopeIdSeparator) : null;
}

/** 🔗️ Parses one `schema://<scope id>/<ExportId>` binding into its resolution key halves. */
export function parseSchemaExportUri(uri: string, taxonomy: Taxonomy = loadTaxonomy()): { readonly scopeId: string; readonly exportId: string } | null {
  const match = new RegExp(taxonomy.schemaExportResolution.uriPattern, "u").exec(uri);
  const groups = match?.groups;
  return groups?.scope && groups.export ? { scopeId: groups.scope, exportId: groups.export } : null;
}

interface SchemaWalkResult {
  readonly directories: readonly string[];
  readonly files: readonly string[];
}

const GIT_SUBMODULE_PATHS = new Map<string, readonly string[]>();
const GIT_SUBMODULE_PATH_DECLARATION = /^[\t ]*path[\t ]*=[\t ]*(.+?)[\t ]*$/gmu;

/**
 * 🧩️ The repository-relative paths `.gitmodules` declares, memoised per repository root.
 *
 * A submodule is a foreign repository tracked as one gitlink: its files are not this repository's sources
 * and every law that walks the tree would double-count them. Read from the declaration file, never from a
 * `git` subprocess, so the walk stays a pure filesystem read; NFC-normalised because the declaration and
 * the directory entry can spell the same emoji path in different Unicode forms.
 * @see https://git-scm.com/docs/gitmodules
 */
export function gitSubmodulePaths(repoRoot: string): readonly string[] {
  const root = resolve(repoRoot);
  const memoised = GIT_SUBMODULE_PATHS.get(root);
  if (memoised) return memoised;
  let declared: string[] = [];
  try {
    declared = [...readFileSync(join(root, ".gitmodules"), "utf8").matchAll(GIT_SUBMODULE_PATH_DECLARATION)].map((match) => match[1]!.replaceAll("\\", "/").replace(/^\.\//u, "").replace(/\/+$/u, "").normalize("NFC")).filter((path) => path.length > 0);
  } catch {
    declared = [];
  }
  const paths = [...new Set(declared)].sort(byteSort);
  GIT_SUBMODULE_PATHS.set(root, paths);
  return paths;
}

function walkRepositoryTree(repoRoot: string, taxonomy: Taxonomy): SchemaWalkResult {
  const directories: string[] = [];
  const files: string[] = [];
  const opaque = [...Object.values(taxonomy.pathExclusions).map((exclusion) => exclusion.path.replaceAll("\\", "/").replace(/^\.\//u, "").replace(/\/+$/u, "")), ...gitSubmodulePaths(repoRoot)].map((prefix) => prefix.normalize("NFC"));
  const visit = (relDir: string): void => {
    let entries: import("node:fs").Dirent<string>[];
    try {
      entries = readdirSync(join(repoRoot, relDir), { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries.sort((left, right) => byteSort(left.name, right.name))) {
      if (entry.isSymbolicLink()) continue;
      const rel = relDir ? `${relDir}/${entry.name}` : entry.name;
      const key = rel.normalize("NFC");
      if (opaque.some((prefix) => key === prefix || key.startsWith(`${prefix}/`))) continue;
      if (entry.isDirectory()) {
        if (isDiscoverySkipDirectory(entry.name) || entry.name.startsWith(".")) continue;
        directories.push(rel);
        visit(rel);
      } else if (entry.isFile()) files.push(rel);
    }
  };
  visit("");
  return { directories, files };
}

/** 🔎️ First index of `sorted` whose byte order is not below `value` (prefix ranges without a linear scan). */
function lowerBound(sorted: readonly string[], value: string): number {
  let low = 0;
  let high = sorted.length;
  while (low < high) {
    const middle = (low + high) >> 1;
    if (byteSort(sorted[middle]!, value) < 0) low = middle + 1;
    else high = middle;
  }
  return low;
}

function jsonRefOccurrences(value: unknown, pointer: string, out: { pointer: string; ref: string }[]): void {
  if (Array.isArray(value)) {
    value.forEach((item, index) => jsonRefOccurrences(item, `${pointer}/${index}`, out));
    return;
  }
  if (!value || typeof value !== "object") return;
  for (const [key, child] of Object.entries(value as Record<string, unknown>)) {
    if (key === "$ref" && typeof child === "string") out.push({ pointer: `${pointer}/$ref`, ref: child });
    else jsonRefOccurrences(child, `${pointer}/${key.replaceAll("~", "~0").replaceAll("/", "~1")}`, out);
  }
}

/** 🚫️ Every pointer at which the document declares `enum: []`, a keyword no instance can ever satisfy. */
function jsonEmptyEnumPointers(value: unknown, pointer: string, out: string[]): void {
  if (Array.isArray(value)) {
    value.forEach((item, index) => jsonEmptyEnumPointers(item, `${pointer}/${index}`, out));
    return;
  }
  if (!value || typeof value !== "object") return;
  for (const [key, child] of Object.entries(value as Record<string, unknown>)) {
    const next = `${pointer}/${key.replaceAll("~", "~0").replaceAll("/", "~1")}`;
    if (key === "enum" && Array.isArray(child) && child.length === 0) out.push(next);
    else jsonEmptyEnumPointers(child, next, out);
  }
}

/** 🎯️ Whether one JSON pointer addresses an existing member of the document; the empty pointer is the document. */
function jsonPointerResolves(root: unknown, pointer: string): boolean {
  if (pointer === "") return true;
  if (!pointer.startsWith("/")) return false;
  let current: unknown = root;
  for (const raw of pointer.slice(1).split("/")) {
    const key = raw.replaceAll("~1", "/").replaceAll("~0", "~");
    if (Array.isArray(current)) {
      const index = Number(key);
      if (!/^(?:0|[1-9][0-9]*)$/u.test(key) || index >= current.length) return false;
      current = current[index];
      continue;
    }
    if (!current || typeof current !== "object" || !Object.hasOwn(current as object, key)) return false;
    current = (current as Record<string, unknown>)[key];
  }
  return true;
}

/** 🔎️ Whether one non-JSON format leaf declares the named export, by the declaration keywords of that language. */
function schemaFormatDeclaresExport(formatId: string, source: string, exportId: string): boolean {
  const name = exportId.replaceAll(/[\\^$.*+?()[\]{}|]/gu, "\\$&");
  const keywords: Readonly<Record<string, readonly string[]>> = {
    "🦀️rust": ["struct", "enum", "type", "trait", "fn"],
    "🟦️typescript": ["interface", "type", "class", "enum", "const", "function"],
    "🔗️graphql": ["type", "input", "enum", "union", "scalar", "interface"],
    "🛰️protobuf": ["message", "enum", "service"],
  };
  const declared = keywords[formatId];
  if (!declared) return false;
  if (new RegExp(`\\b(?:${declared.join("|")})\\s+${name}\\b`, "u").test(source)) return true;
  if (formatId === "🦀️rust") return new RegExp(`\\bpub\\s+use\\b[^;]*\\b${name}\\b`, "u").test(source);
  if (formatId !== "🟦️typescript") return false;
  return new RegExp(`\\bparse${name}\\b`, "u").test(source) || new RegExp(`\\bexport\\b(?:\\s+type)?\\s*\\{[^}]*\\b${name}\\b[^}]*\\}`, "u").test(source);
}

/** 🧪️ Distinguishes embedded schema authority from schema-shaped input specimens. */
function schemaEmbeddedExampleAuthority(subject: unknown): boolean {
  if (!subject || typeof subject !== "object") return false;
  if (Array.isArray(subject)) return subject.some(schemaEmbeddedExampleAuthority);
  return Object.entries(subject as Record<string, unknown>).some(([key, value]) => {
    if (/^(?:input|inputs|value|values|payload|request|document|documents|files|expect)$/u.test(key) || /^expected(?:$|[A-Z])/u.test(key)) return false;
    if (/(?:^|[A-Z])schema$/iu.test(key) && value && typeof value === "object" && !Array.isArray(value)) {
      const schema = value as Record<string, unknown>;
      if (["$schema", "$ref", "type", "properties", "items", "allOf", "anyOf", "oneOf", "enum", "const"].some((keyword) => Object.hasOwn(schema, keyword))) return true;
    }
    return schemaEmbeddedExampleAuthority(value);
  });
}

/** 🧫️ Recognizes test corpus contracts from their examples and expectations independently of titles. */
function schemaTestCorpusDefinition(exportId: string, subject: unknown, document: Record<string, unknown>): boolean {
  const producedRecord = /(?:Report|Result|Progress|Outcome|Diagnostic|Coverage)(?:V\d+)?$/u.test(exportId);
  const namedCorpus = /(?:Fixture|Corpus|Cases|(?:^|[A-Z])Vectors?(?:File)?$)/iu.test(exportId);
  const visited = [new Set<unknown>(), new Set<unknown>()];
  const inspect = (value: unknown, testCases = false): boolean => {
    const seen = visited[Number(testCases)]!;
    if (!value || typeof value !== "object" || seen.has(value)) return false;
    seen.add(value);
    if (Array.isArray(value)) return value.some((child) => inspect(child, testCases));
    const node = value as Record<string, unknown>;
    const reference = typeof node.$ref === "string" ? node.$ref.match(/^#\/(\$defs|definitions)\/([^/]+)$/u) : null;
    if (reference && inspect((document[reference[1]!] as Record<string, unknown> | undefined)?.[reference[2]!], testCases)) return true;
    const properties = node.properties && typeof node.properties === "object" ? node.properties as Record<string, unknown> : {};
    const expectations = Object.keys(properties).filter((key) => /^(?:expect$|expected(?:$|[A-Z]))/u.test(key));
    if (!producedRecord && expectations.length && (testCases || namedCorpus || ["grants", "hostile", "hostiles", "sourceFixture"].some((key) => Object.hasOwn(properties, key)))) return true;
    if (!producedRecord && testCases && ["accepted", "valid"].some((key) => Object.hasOwn(properties, key))) return true;
    const marker = properties.schema && typeof properties.schema === "object" ? (properties.schema as Record<string, unknown>).const : undefined;
    if (typeof marker === "string" && /(?:fixture|corpus|test[-.]cases)/iu.test(marker)) return true;
    const fixedProperties = Object.entries(properties).filter(([, child]) => child && typeof child === "object" && Object.hasOwn(child, "const"));
    const fixed = new Map(fixedProperties), fields = (child: unknown): Record<string, unknown> => child && typeof child === "object" ? ((child as Record<string, unknown>).properties as Record<string, unknown> | undefined) ?? {} : {};
    const items = (key: string): Record<string, unknown> => { const child = properties[key]; return child && typeof child === "object" ? ((child as Record<string, unknown>).items as Record<string, unknown> | undefined) ?? {} : {}; };
    const owns = (record: Record<string, unknown>, keys: readonly string[]): boolean => keys.every(key => Object.hasOwn(record, key));
    if (node.additionalProperties === false) {
      if (["package", "module", "manifest", "library", "mount", "dependencies", "publicEntries", "forbiddenProviders"].every(key => fixed.has(key))) return true;
      const owners = properties.owners as Record<string, unknown> | undefined;
      if (owns(properties, ["owners", "routers", "artifactDefinitions", "inputs", "registration"]) && owners && typeof owners.minItems === "number" && owners.minItems > 0 && owners.minItems === owners.maxItems) return true;
      const revisions = properties.rows as Record<string, unknown> | undefined;
      if (revisions && typeof revisions.minItems === "number" && revisions.minItems > 0 && revisions.minItems === revisions.maxItems && owns(fields(items("rows")), ["path", "originalSha256", "currentSha256"])) return true;
      const contexts = fields(items("contexts")), phases = contexts.phases as Record<string, unknown> | undefined;
      if (Object.hasOwn(properties, "imports") && owns(contexts, ["id", "source", "phases"]) && phases && owns(fields(phases.items), ["file", "projects", "packages", "locked", "targets"])) return true;
      if (owns(properties, ["counts", "rows", "refused", "encodings"]) && ["owner", "table", "columns", "identity"].every(key => fixed.has(key))) return true;
      if (["renderId", "kind", "group", "handle", "label", "revision", "expectedBytes"].every(key => fixed.has(key))) return true;
      const emptySegments = fields(properties.emptySegments), capacityRefusal = emptySegments.accepted as Record<string, unknown> | undefined;
      if (owns(properties, ["byteGrants", "capacityGrant", "cancelAt", "cases", "emptySegments"]) && owns(fields(items("cases")), ["code", "message", "target"]) && Object.hasOwn(emptySegments, "count") && capacityRefusal?.const === false) return true;
      const unchanged = properties.sourceUnchanged as Record<string, unknown> | undefined, changed = properties.changedSourceAccepted as Record<string, unknown> | undefined;
      if (owns(properties, ["cancelAt", "sourceUnchanged", "changedSourceAccepted"]) && unchanged?.const === true && changed?.const === false) return true;
      if (owns(properties, ["bodyBytes", "text", "repeat", "originalUnchanged", "terminalEmpty"]) && fixed.has("bodyBytes") && ["originalUnchanged", "terminalEmpty"].every(key => (properties[key] as Record<string, unknown> | undefined)?.const === true)) return true;
      if (owns(properties, ["prefix", "prefixRepeat", "cancelAt", "comparisons", "objectEntries"]) && ["bodyBytes", "payloadChunkBytes", "treeDepth", "maximumCursorBytes"].every(key => fixed.has(key)) && owns(fields(items("comparisons")), ["left", "right", "ordering"])) return true;
      if (owns(properties, ["initial", "first", "latest", "remote", "unsubmitted", "commandsAfterEnterAndBlur", "commandsAfterNextBlur", "draftAfterFirstEcho", "conflictAfterFirstEcho", "dirtyAfterFinalEcho"])) return true;
      const refusals = fields(properties.refusals);
      if (owns(properties, ["fields", "copy", "frontier", "maximumBytes", "tinyMaximumBytes", "recursiveDepth", "refusals"]) && owns(fields(properties.copy), ["repeatCount", "cancelAt"]) && owns(fields(properties.frontier), ["fieldCount", "cancelAt"]) && ["ownership", "cancellation"].every(key => refusals[key] && typeof refusals[key] === "object" && Object.hasOwn(refusals[key]!, "const"))) return true;
    }
    const fixedTrials = fixedProperties.some(([key, child]) => /(?:Grants|Frontiers|Cuts|budgetCases|zeroGrants)$/u.test(key) && Array.isArray((child as Record<string, unknown>).const));
    if (fixedTrials && fixedProperties.some(([key]) => /(?:Survives|Allocations|Readable|Mutates|Unchanged|RequiresTerminal|AfterClose|BeforeFinalReader)/u.test(key))) return true;
    if (Object.entries(properties).some(([key, child]) => {
      const examples = child && typeof child === "object" ? (child as Record<string, unknown>).const : undefined;
      return Array.isArray(examples) && (["cases", "vectors", "scenarios", "laws"].includes(key) || examples.some((example) => example && typeof example === "object" && Object.keys(example).some((field) => /^(?:expect$|expected(?:$|[A-Z]))/u.test(field))));
    })) return true;
    if (Object.entries(properties).some(([key, child]) => inspect(child, testCases || /(?:^|[A-Z])(?:cases|vectors|scenarios)$/iu.test(key)))) return true;
    return Object.entries(node).some(([key, child]) => !["properties", "$defs", "definitions"].includes(key) && inspect(child, testCases));
  };
  return inspect(subject);
}

function readSchemaDocument(repoRoot: string, path: string, taxonomy: Taxonomy, diagnostics: SchemaScopeDiagnostic[]): SchemaScopeDocument | null {
  let parsed: Record<string, unknown>;
  try {
    parsed = JSON.parse(readFileSync(join(repoRoot, path), "utf8")) as Record<string, unknown>;
  } catch (error) {
    diagnostics.push({ code: "schema-document-unparseable", path, detail: (error as Error).message });
    return null;
  }
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    diagnostics.push({ code: "schema-document-not-object", path, detail: "A schema module leaf must be a JSON Schema object." });
    return null;
  }
  const resolution = taxonomy.schemaExportResolution;
  const id = typeof parsed.$id === "string" ? parsed.$id : null;
  const dialect = typeof parsed.$schema === "string" ? parsed.$schema : null;
  if (!id) diagnostics.push({ code: "schema-module-id-missing", path, detail: `Declare $id as ${resolution.idBase}<scope path>/<facet>.json.` });
  const parts = id ? schemaDocumentIdParts(id, taxonomy) : null;
  const scopeId = parts ? parts.scopePath.join(resolution.scopeIdSeparator) : null;
  if (id && !scopeId) diagnostics.push({ code: "schema-document-id-unaddressable", path, detail: `$id ${JSON.stringify(id)} does not resolve to a dotted scope id under ${resolution.idBase}.` });
  if (dialect !== taxonomy.schemaJsonDialect) diagnostics.push({ code: "schema-dialect-not-draft-07", path, detail: `$schema must be ${taxonomy.schemaJsonDialect}, got ${JSON.stringify(dialect)}.` });
  if (parsed["x-semio-mutationKinds"] !== undefined) diagnostics.push({ code: "schema-mutation-aggregate-kinds-redundant", path, detail: "x-semio-mutationKinds restates the oneOf $ref union and has no reader; the aggregate's $refs are the identity." });
  const exportPattern = new RegExp(resolution.exportIdPattern, "u");
  const formatKeys = Object.keys(taxonomy.schemaFormats).sort(byteSort);
  const exports: string[] = [];
  const exportFormats: Record<string, readonly string[]> = {};
  const restriction = (subject: unknown, exportId: string): void => {
    const declared = subject && typeof subject === "object" ? (subject as Record<string, unknown>)["x-semio-formats"] : undefined;
    if (declared === undefined) return;
    if (!Array.isArray(declared) || declared.length === 0 || declared.some((entry) => typeof entry !== "string" || !formatKeys.includes(entry))) {
      diagnostics.push({ code: "schema-export-formats-annotation-invalid", path, detail: `${exportId} declares x-semio-formats ${JSON.stringify(declared)}; restricted support is a non-empty subset of ${formatKeys.join(", ")}.` });
      return;
    }
    exportFormats[exportId] = [...new Set(declared as string[])].sort(byteSort);
  };
  const rootExport = typeof parsed[resolution.rootExportKeyword] === "string" ? String(parsed[resolution.rootExportKeyword]) : null;
  const rootIsObject = parsed.type === "object" || (parsed.type === undefined && typeof parsed.properties === "object" && parsed.properties !== null);
  const rootIsCorpus = schemaTestCorpusDefinition(rootExport ?? "", parsed, parsed);
  if (rootIsCorpus) diagnostics.push({ code: "schema-fixture-defines-schema", path, detail: `${rootExport ?? "The document root"} defines a test corpus contract. Examples use actual domain contracts and cannot own separate schemas.` });
  if (rootExport && rootIsObject && !rootIsCorpus) {
    if (exportPattern.test(rootExport)) {
      exports.push(rootExport);
      restriction(parsed, rootExport);
    } else diagnostics.push({ code: "schema-export-id-invalid", path, detail: `Root ${resolution.rootExportKeyword} ${JSON.stringify(rootExport)} is not a PascalCase export id.` });
  }
  const defs = parsed[resolution.exportsKeyword];
  const defRows = defs && typeof defs === "object" && !Array.isArray(defs) ? (defs as Record<string, unknown>) : {};
  const localDefinitions = parsed.definitions && typeof parsed.definitions === "object" && !Array.isArray(parsed.definitions) ? parsed.definitions as Record<string, unknown> : {};
  for (const [key, value] of Object.entries(localDefinitions)) if (schemaTestCorpusDefinition(key, value, parsed)) diagnostics.push({ code: "schema-fixture-defines-schema", path, detail: `${key} defines a test corpus contract. Examples use actual domain contracts and cannot own separate schemas.` });
  const defKeys = Object.keys(defRows);
  for (const key of defKeys) {
    if (schemaTestCorpusDefinition(key, defRows[key], parsed)) diagnostics.push({ code: "schema-fixture-defines-schema", path, detail: `${key} defines a test corpus contract. Examples use actual domain contracts and cannot own separate schemas.` });
    else if (!exportPattern.test(key)) diagnostics.push({ code: "schema-export-id-invalid", path, detail: `${resolution.exportsKeyword} key ${JSON.stringify(key)} is not a PascalCase export id.` });
    else if (!exports.includes(key)) {
      exports.push(key);
      restriction(defRows[key], key);
    }
  }
  const emptyEnums: string[] = [];
  jsonEmptyEnumPointers(parsed, "", emptyEnums);
  for (const pointer of emptyEnums) diagnostics.push({ code: "schema-enum-empty", path, detail: `${pointer} declares enum: [], which no instance can satisfy. State the intent instead: propertyNames: false or maxProperties: 0 for "no member is admitted", or delete the keyword.` });
  const occurrences: { pointer: string; ref: string }[] = [];
  jsonRefOccurrences(parsed, "", occurrences);
  const references: SchemaScopeReference[] = [];
  for (const { pointer, ref } of occurrences) {
    if (ref.startsWith("#")) {
      const local = ref.slice(1);
      const prefix = `/${resolution.exportsKeyword}/`;
      const exportId = local.startsWith(prefix) && !local.slice(prefix.length).includes("/") ? local.slice(prefix.length) : null;
      if (!jsonPointerResolves(parsed, local)) diagnostics.push({ code: "schema-ref-unresolved", path, detail: `${pointer} references ${JSON.stringify(ref)}, which this document does not declare.` });
      references.push({ documentPath: path, pointer, ref, targetScopeId: scopeId, targetExportId: exportId, local: true });
      continue;
    }
    if (!ref.startsWith(resolution.idBase)) {
      diagnostics.push({ code: "schema-ref-unresolved", path, detail: `${pointer} uses ${JSON.stringify(ref)}; a cross-scope reference names the target $id under ${resolution.idBase}.` });
      continue;
    }
    const [base, fragment = ""] = ref.split("#");
    const targetScopeId = schemaScopeIdFromDocumentId(base!, taxonomy);
    const prefix = `/${resolution.exportsKeyword}/`;
    const exportId = fragment.startsWith(prefix) ? fragment.slice(prefix.length) : null;
    if (!targetScopeId || (fragment && !exportId)) {
      diagnostics.push({ code: "schema-ref-unresolved", path, detail: `${pointer} uses ${JSON.stringify(ref)}; a cross-scope reference is <target $id>#${prefix}<ExportId>.` });
      continue;
    }
    references.push({ documentPath: path, pointer, ref, targetScopeId, targetExportId: exportId, local: false });
  }
  return { path, scopeId, scopePath: parts?.scopePath ?? null, id, facetFilename: parts ? parts.facet.replace(/\.json$/u, "") : null, dialect, exports, exportFormats, references };
}

/**
 * 🧬️ Walks every `🧬️schema` module, reads its documents and derives the scope catalog and every finding.
 *
 * A module's content is the set of walked leaves that are still readable when the walk reaches them, so a
 * file a concurrent writer removes mid-walk is absent from `hashes`, `documents` and the catalog row alike
 * rather than aborting the run or outliving its deletion (ledger row 109).
 */
export function inventorySchemaScopes(repoRoot: string, taxonomy: Taxonomy = loadCatalogTaxonomy()): SchemaScopeInventory {
  const root = resolve(repoRoot);
  const { directories, files } = walkRepositoryTree(root, taxonomy);
  const facetDir = taxonomy.schemaScopeOwnerLevels.facetDirName;
  const resolution = taxonomy.schemaExportResolution;
  const diagnostics: SchemaScopeDiagnostic[] = [];
  const matcher = createTaxonomyPathMatcher();
  const modulePaths = directories.filter((path) => path.endsWith(`/${facetDir}`) || path === facetDir).sort(byteSort);
  const modulePathSet = new Set(modulePaths);
  const fileSet = new Set(files);
  const sortedFiles = [...files].sort(byteSort);
  const filesUnder = (prefix: string): string[] => {
    const start = lowerBound(sortedFiles, `${prefix}/`);
    const found: string[] = [];
    for (let index = start; index < sortedFiles.length && sortedFiles[index]!.startsWith(`${prefix}/`); index += 1) found.push(sortedFiles[index]!);
    return found;
  };
  const formatLeaves = Object.entries(taxonomy.schemaFormats).map(([formatId, format]) => [formatId, canonicalPrimaryFilenameForKind(format.fileKindId, taxonomy)] as const);
  const ownerPaths = modulePaths.map((modulePath) => schemaScopeModuleOwnerPath(modulePath, taxonomy, matcher));
  const nestedOwners = new Set(ownerPaths);
  const facetChainDirs = new Set(taxonomy.schemaChildDirs);
  const ownedByNestedScope = (path: string, modulePath: string): boolean => {
    const segments = path.slice(modulePath.length + 1).split("/");
    for (let index = 1; index < segments.length; index += 1) if (nestedOwners.has(`${modulePath}/${segments.slice(0, index).join("/")}`)) return true;
    return false;
  };
  const canonicalLeaves = new Set(formatLeaves.map(([, leaf]) => leaf));
  const normativeFormatId = taxonomy.schemaFacetKinds![taxonomy.schemaDefaultFacetKind]!.normativeFormat;
  const normativeJsonLeaf = canonicalPrimaryFilenameForKind(taxonomy.schemaFormats[normativeFormatId]!.fileKindId, taxonomy);
  const isFacetLeaf = (path: string, modulePath: string, leaves: ReadonlySet<string>): boolean => {
    const segments = path.slice(modulePath.length + 1).split("/");
    return leaves.has(segments.at(-1)!) && segments.slice(0, -1).every((segment) => facetChainDirs.has(segment));
  };
  const descriptorLeafName = canonicalPrimaryFilenameForKind(taxonomy.mutationDescriptorFileKindId, taxonomy);
  const inertDeclarations = new Map<string, ReadonlySet<string>>();
  const inertSchemaData = (path: string): boolean => {
    if (schemaCollectionContractPath(path, taxonomy, matcher)) return false;
    const segments = path.split("/");
    for (let index = segments.length - 1; index > 0; index -= 1) {
      const caseFile = `${segments.slice(0, index).join("/")}/${descriptorLeafName}`;
      if (!fileSet.has(caseFile)) continue;
      let declared = inertDeclarations.get(caseFile);
      if (!declared) {
        let named: string[] = [];
        try {
          const value = (JSON.parse(readFileSync(join(root, caseFile), "utf8")) as Record<string, unknown>)[taxonomy.schemaScopeOwnerLevels.inertSchemaDataKeyword];
          if (Array.isArray(value)) named = value.filter((entry): entry is string => typeof entry === "string");
        } catch {
          named = [];
        }
        declared = new Set(named);
        inertDeclarations.set(caseFile, declared);
      }
      if (declared.has(segments.slice(index).join("/"))) return true;
    }
    return false;
  };
  const modules: SchemaScopeModule[] = [];
  const rootScopePaths = new Map<string, readonly string[] | null>();
  const rootDocuments = new Map<string, SchemaScopeDocument>();
  for (const [index, modulePath] of modulePaths.entries()) {
    const ownerPath = ownerPaths[index]!;
    if (schemaScopeCollectionPath(modulePath, taxonomy, matcher)) {
      continue;
    }
    const level = schemaScopeOwnerLevel(ownerPath, taxonomy, matcher);
    if (!level) diagnostics.push({ code: "schema-owner-ineligible", path: modulePath, detail: `${ownerPath || "."} is not a declared schemaScopeOwnerLevels level.` });
    const walked = filesUnder(modulePath).filter((path) => !ownedByNestedScope(path, modulePath) && !schemaScopeOwnerExcluded(path, taxonomy, matcher) && isFacetLeaf(path, modulePath, canonicalLeaves));
    const hashes: Record<string, string> = {};
    const owned: string[] = [];
    for (const path of walked) {
      let bytes: Buffer;
      try {
        bytes = readFileSync(join(root, path));
      } catch {
        continue;
      }
      owned.push(path);
      hashes[path.slice(modulePath.length + 1)] = createHash("sha256").update(bytes).digest("hex");
    }
    const facetKindId = resolveSchemaFacetKind(modulePath, taxonomy);
    const formats: Record<string, string> = {};
    for (const [formatId, leaf] of formatLeaves) if (fileSet.has(`${modulePath}/${leaf}`)) formats[formatId] = `${modulePath}/${leaf}`;
    const jsonLeaf = canonicalPrimaryFilenameForKind(taxonomy.schemaFormats[taxonomy.schemaFacetKinds![facetKindId]!.normativeFormat]!.fileKindId, taxonomy);
    const documents = jsonLeaf.endsWith(".json") ? owned.filter((path) => path.endsWith(`/${jsonLeaf}`)).map((path) => readSchemaDocument(root, path, taxonomy, diagnostics)).filter((document): document is SchemaScopeDocument => document !== null) : [];
    const rootDocument = documents.find((document) => document.path === `${modulePath}/${jsonLeaf}`) ?? null;
    const rootScopeId = rootDocument?.scopeId ?? null;
    const rootScopePath = rootDocument?.scopePath ?? null;
    rootScopePaths.set(modulePath, rootScopePath);
    if (rootDocument) rootDocuments.set(modulePath, rootDocument);
    if (documents.length > 0 && !rootScopeId) diagnostics.push({ code: "schema-module-id-missing", path: modulePath, detail: `${modulePath}/${jsonLeaf} must declare the $id that names this module's scope.` });
    const mutationsPrefix = `${taxonomy.schemaScopeOwnerLevels.mutationsFacetDirName}/`;
    if (rootScopeId && rootScopePath) for (const document of documents) {
      if (document === rootDocument || !document.scopePath) continue;
      const relative = document.path.slice(modulePath.length + 1);
      if (relative === `${mutationsPrefix}${jsonLeaf}` || relative.startsWith(mutationsPrefix + mutationsPrefix)) continue;
      if (document.scopePath.length >= rootScopePath.length && document.scopePath.slice(0, rootScopePath.length).join("/") === rootScopePath.join("/")) continue;
      diagnostics.push({ code: "schema-module-id-inconsistent", path: document.path, detail: `$id ${JSON.stringify(document.id)} must keep this module's scope path ${resolution.idBase}${rootScopePath.join("/")}/ and vary only the facet filename; a facet document never deepens the scope.` });
    }
    modules.push({ modulePath, ownerPath, level, facetKindId, scopeId: rootScopeId, formats, documents, hashes });
  }
  for (const path of sortedFiles) {
    if (!schemaScopeCollectionPath(path, taxonomy, matcher)) continue;
    if (!schemaCollectionContractPath(path, taxonomy, matcher)) {
      if (!path.endsWith(".json") || inertSchemaData(path)) continue;
      try {
        const document = JSON.parse(readFileSync(join(root, path), "utf8")) as { $schema?: unknown } | null;
        const rootContract = document && typeof document.$schema === "string" && /^https?:\/\/json-schema\.org\//u.test(document.$schema);
        if (!rootContract && !schemaEmbeddedExampleAuthority(document)) continue;
      } catch {
        continue;
      }
    }
    diagnostics.push({ code: "schema-fixture-defines-schema", path, detail: `${path} defines a contract facet inside examples. Move the contract into its domain owner's ${facetDir} module; inert parser inputs must be ordinary named data files outside contract facets.` });
  }
  const declaredSemanticKind = (leafOwnerPath: string): string | null => {
    try {
      const kind = (JSON.parse(readFileSync(join(root, leafOwnerPath, descriptorLeafName), "utf8")) as { semanticKind?: unknown }).semanticKind;
      return typeof kind === "string" && kind ? kind : null;
    } catch {
      return null;
    }
  };
  const mutationsDir = taxonomy.schemaScopeOwnerLevels.mutationsFacetDirName;
  const mutationRootModule = (leafOwnerPath: string): { readonly module: string; readonly depth: number } | null => {
    const segments = leafOwnerPath.split("/");
    for (let index = segments.length - 1; index >= 1; index -= 1) {
      if (segments[index] !== mutationsDir || segments[index - 1] !== facetDir) continue;
      return { module: segments.slice(0, index).join("/"), depth: segments.length - index - 1 };
    }
    return null;
  };
  const mutationLeafOwners: string[] = [];
  for (const path of sortedFiles) {
    if (path.slice(path.lastIndexOf("/") + 1) !== descriptorLeafName) continue;
    const ownerPath = path.slice(0, path.lastIndexOf("/"));
    const enclosing = mutationRootModule(ownerPath);
    if (!enclosing || enclosing.depth < 1 || enclosing.depth > 2 || schemaScopeCollectionPath(ownerPath, taxonomy, matcher)) continue;
    if (declaredSemanticKind(ownerPath) !== null) mutationLeafOwners.push(ownerPath);
  }
  for (const leafOwnerPath of mutationLeafOwners) {
    const enclosing = mutationRootModule(leafOwnerPath)!;
    const enclosingScopePath = rootScopePaths.get(enclosing.module) ?? null;
    const kind = declaredSemanticKind(leafOwnerPath);
    const expectedPath = [...(enclosingScopePath ?? ["<enclosing scope path>"]), resolution.mutationScopeSegment, kind ?? "<semanticKind>"];
    const expected = `${resolution.idBase}${[...expectedPath, resolution.mutationLeafFacetFilename].join("/")}`;
    const leafModulePath = `${leafOwnerPath}/${facetDir}`;
    const document = rootDocuments.get(leafModulePath) ?? null;
    if (!document) {
      diagnostics.push({ code: "schema-mutation-leaf-schema-absent", path: leafModulePath, detail: `The leaf is the authority for its own payload, so ${leafModulePath}/${normativeJsonLeaf} must exist and declare $id ${expected}.` });
      continue;
    }
    if (document.id === expected) continue;
    diagnostics.push({ code: "schema-mutation-leaf-id", path: document.path, detail: `$id ${JSON.stringify(document.id)} must be ${expected}: a mutation leaf is its own scope, not a facet of its enclosing module.` });
  }
  for (const module of modules) {
    const rootScopePath = rootScopePaths.get(module.modulePath) ?? null;
    if (!rootScopePath) continue;
    const aggregate = module.documents.find((document) => document.path === `${module.modulePath}/${mutationsDir}/${normativeJsonLeaf}`);
    if (!aggregate) continue;
    const expected = `${resolution.idBase}${[...rootScopePath, resolution.mutationAggregateFacetFilename].join("/")}`;
    if (aggregate.id === expected) continue;
    diagnostics.push({ code: "schema-mutation-aggregate-id", path: aggregate.path, detail: `$id ${JSON.stringify(aggregate.id)} must be ${expected}: an aggregate is the mutations facet of its own module and never deepens the scope.` });
  }
  const documentsById = new Map<string, { readonly scopeId: string | null; readonly path: string; readonly exports: ReadonlySet<string> }>();
  for (const module of modules) for (const document of module.documents) {
    if (!document.id) continue;
    const existing = documentsById.get(document.id);
    if (existing) {
      diagnostics.push({ code: "schema-document-id-duplicate", path: document.path, detail: `$id ${document.id} is already declared by ${existing.path}; a document $id is the resolution key and is unique repository-wide.` });
      continue;
    }
    documentsById.set(document.id, { scopeId: module.level ? module.scopeId : null, path: document.path, exports: new Set(document.exports) });
  }
  const byScope = new Map<string, SchemaScopeModule[]>();
  for (const module of modules) if (module.scopeId && module.level) byScope.set(module.scopeId, [...(byScope.get(module.scopeId) ?? []), module]);
  const scopes: Record<string, SchemaCatalogScope> = {};
  for (const [scopeId, claimants] of [...byScope.entries()].sort(([left], [right]) => byteSort(left, right))) {
    const owner = claimants[0]!;
    if (claimants.length > 1) for (const claimant of claimants) diagnostics.push({ code: "schema-scope-ambiguous", path: claimant.modulePath, detail: `Scope ${scopeId} is declared by ${claimant.modulePath}/${canonicalPrimaryFilenameForKind(taxonomy.schemaFormats[taxonomy.schemaFacetKinds![claimant.facetKindId]!.normativeFormat]!.fileKindId, taxonomy)} and by ${claimants.filter((other) => other !== claimant).map((other) => other.modulePath).join(", ")}; ${owner.modulePath} holds the catalog row.` });
    const ownerScopePath = rootScopePaths.get(owner.modulePath) ?? null;
    const exports: Record<string, SchemaCatalogExport> = {};
    for (const document of [...owner.documents].sort((left, right) => byteSort(left.path, right.path))) {
      const relative = document.path.slice(owner.modulePath.length + 1);
      const suffix = ownerScopePath && document.scopePath && document.scopePath.length >= ownerScopePath.length ? document.scopePath.slice(ownerScopePath.length) : [];
      const facet = document.facetFilename ? [...suffix, document.facetFilename].join("/") : relative.slice(0, Math.max(0, relative.lastIndexOf("/"))) || taxonomy.schemaDefaultFacetKind;
      for (const exportId of document.exports) {
        const existing = exports[exportId];
        if (existing) {
          if (existing.file !== relative) diagnostics.push({ code: "schema-export-id-duplicate", path: document.path, detail: `Export ${exportId} is already declared by ${owner.modulePath}/${existing.file}; one scope resolves each export id to exactly one file.` });
          continue;
        }
        exports[exportId] = { file: relative, facet };
      }
    }
    const dependsOn = [...new Set(owner.documents.flatMap((document) => document.references).filter((reference) => !reference.local).map((reference) => documentsById.get(reference.ref.split("#")[0]!)?.scopeId).filter((value): value is string => value !== null && value !== undefined && value !== scopeId))].sort(byteSort);
    const hashes = Object.fromEntries(Object.entries(owner.hashes).sort(([left], [right]) => byteSort(left, right)));
    const formats = Object.fromEntries(Object.entries(owner.formats).map(([formatId, path]) => [formatId, path.slice(owner.modulePath.length + 1)]));
    scopes[scopeId] = { path: owner.modulePath, level: owner.level!, facetKind: owner.facetKindId, formats, exports: Object.fromEntries(Object.entries(exports).sort(([left], [right]) => byteSort(left, right))), dependsOn, hashes };
  }
  for (const module of modules) for (const document of module.documents) for (const reference of document.references) {
    if (reference.local) continue;
    const target = documentsById.get(reference.ref.split("#")[0]!);
    if (!target) diagnostics.push({ code: "schema-ref-unresolved", path: document.path, detail: `${reference.pointer} references ${JSON.stringify(reference.ref)}; no catalogued document declares that $id.` });
    else if (reference.targetExportId && !target.exports.has(reference.targetExportId)) diagnostics.push({ code: "schema-ref-unresolved", path: document.path, detail: `${reference.pointer} references export ${JSON.stringify(reference.targetExportId)}, which ${target.path} does not declare.` });
    else if (target.scopeId === null) diagnostics.push({ code: "schema-cross-scope-dependency-uncataloged", path: document.path, detail: `${reference.pointer} resolves into ${target.path}, which no catalogued scope owns; a module compiles only against the scopes its dependsOn names.` });
    else if (module.scopeId && module.level && byScope.get(module.scopeId)?.[0] === module && target.scopeId !== module.scopeId && !(scopes[module.scopeId]?.dependsOn ?? []).includes(target.scopeId)) diagnostics.push({ code: "schema-cross-scope-dependency-forbidden", path: document.path, detail: `${reference.pointer} crosses into scope ${target.scopeId}, which ${module.scopeId} does not declare in dependsOn.` });
  }
  for (const [scopeId, scope] of Object.entries(scopes)) {
    const provided = Object.keys(scope.formats).filter((formatId) => formatId !== normativeFormatId);
    if (provided.length === 0) continue;
    const sources = new Map<string, string>();
    for (const formatId of provided) {
      try {
        sources.set(formatId, readFileSync(join(root, scope.path, scope.formats[formatId]!), "utf8"));
      } catch {
        sources.set(formatId, "");
      }
    }
    const restrictions = new Map<string, readonly string[]>();
    for (const module of byScope.get(scopeId) ?? []) for (const document of module.documents) for (const [exportId, formats] of Object.entries(document.exportFormats)) restrictions.set(exportId, formats);
    for (const [exportId, declaration] of Object.entries(scope.exports)) {
      const restricted = restrictions.get(exportId);
      for (const formatId of provided) {
        if (restricted && !restricted.includes(formatId)) continue;
        if (schemaFormatDeclaresExport(formatId, sources.get(formatId) ?? "", exportId)) continue;
        diagnostics.push({ code: "schema-export-incomplete", path: `${scope.path}/${scope.formats[formatId]!}`, detail: `${scopeId} declares export ${exportId} in ${declaration.file}; ${formatId} carries no declaration of it. Provide it, or annotate the export with x-semio-formats to declare restricted support honestly.` });
      }
    }
  }
  const placement: SchemaScopeDiagnostic[] = [];
  let reportedAncestor: string | null = null;
  for (const path of [...files, ...directories].sort(byteSort)) {
    if (Object.hasOwn(resolution.placementExceptions, path)) continue;
    if (modulePathSet.has(path) || inertSchemaData(path)) continue;
    if (reportedAncestor && path.startsWith(`${reportedAncestor}/`)) continue;
    const pattern = resolution.forbiddenPlacementPatterns.find((candidate) => matcher.matches(path, candidate));
    if (!pattern) continue;
    reportedAncestor = path;
    placement.push({ code: "schema-placement-forbidden-filename", path, detail: `${pattern} ceases to exist: move the contract into its owner's ${facetDir} module.` });
  }
  const catalog: SchemaCatalog = {
    contractId: resolution.catalogContractId,
    catalogVersion: 1,
    generator: resolution.generator,
    taxonomySchemaVersion: taxonomy.schemaVersion,
    jsonSchemaDialect: taxonomy.schemaJsonDialect,
    scopes,
  };
  return { modules, catalog, diagnostics: diagnostics.slice().sort((left, right) => byteSort(left.path, right.path) || byteSort(left.code, right.code) || byteSort(left.detail, right.detail)), placement };
}

/** 📇️ Deterministic catalog bytes; the generated file is exactly this rendering. */
export function renderSchemaCatalog(catalog: SchemaCatalog): string {
  return `${JSON.stringify(catalog, null, 2)}\n`;
}

/** 📓️ Markdown index of every catalogued scope, its exports and its cross-scope dependencies. */
export function renderSchemaCatalogDocument(catalog: SchemaCatalog): string {
  const lines = [
    "# 🧬️ Schema scope catalog",
    "",
    `Generated by \`${catalog.generator}\` — never hand-edited.`,
    "",
    `- contract: \`${catalog.contractId}\``,
    `- taxonomy schemaVersion: \`${catalog.taxonomySchemaVersion}\``,
    `- JSON Schema dialect: \`${catalog.jsonSchemaDialect}\``,
    `- scopes: \`${Object.keys(catalog.scopes).length}\``,
    "",
    "| Scope | Level | Module | Exports | Depends on |",
    "| --- | --- | --- | --- | --- |",
  ];
  for (const [scopeId, scope] of Object.entries(catalog.scopes)) {
    lines.push(`| \`${scopeId}\` | ${scope.level} | \`${scope.path}\` | ${Object.entries(scope.exports).map(([exportId, declaration]) => `\`${exportId}\` (\`${declaration.file}\`)`).join(", ") || "—"} | ${scope.dependsOn.map((value) => `\`${value}\``).join(", ") || "—"} |`);
  }
  lines.push("");
  return lines.join("\n");
}

/** 🦀️ One `(scope, export, format)` triple the Rust `schema_export_catalog_entries()` registry resolves to a non-empty leaf. */
export interface SchemaRustEntry {
  readonly scope: string;
  readonly export: string;
  readonly format: string;
}

/** 🦀️ The dump `schema verify --rust-entries <file>` consumes; `contractId` is `schemaExportResolution.rustEntriesContractId`. */
export interface SchemaRustEntryDump {
  readonly contractId: string;
  readonly generator: string;
  readonly entries: readonly SchemaRustEntry[];
}

/**
 * 🦀️ Cross-checks the generated catalog against the Rust registry dump on the `(scope, export, format)` key.
 * Only scopes the dump declares are compared in both directions; catalogued scopes the dump never mentions are
 * reported as `rust-scope-unregistered` when `complete` is set, so the gate is usable while registration lands.
 */
export function schemaRustEntryDiagnostics(catalog: SchemaCatalog, dump: SchemaRustEntryDump, taxonomy: Taxonomy = loadCatalogTaxonomy(), complete = false): SchemaScopeDiagnostic[] {
  const resolution = taxonomy.schemaExportResolution;
  const path = resolution.catalogPath;
  const diagnostics: SchemaScopeDiagnostic[] = [];
  if (dump.contractId !== resolution.rustEntriesContractId) return [{ code: "rust-entries-contract-unknown", path, detail: `The dump declares contractId ${JSON.stringify(dump.contractId)}; ${resolution.rustEntriesContractId} is the declared shape.` }];
  const asciiByKey = resolution.formatIds;
  const known = new Set(Object.values(asciiByKey));
  const declared = new Set(dump.entries.map((entry) => entry.scope));
  const catalogTriples = new Set<string>();
  for (const [scopeId, scope] of Object.entries(catalog.scopes)) {
    if (!declared.has(scopeId)) continue;
    for (const exportId of Object.keys(scope.exports)) for (const formatKey of Object.keys(scope.formats)) if (asciiByKey[formatKey]) catalogTriples.add(`${scopeId}\0${exportId}\0${asciiByKey[formatKey]}`);
  }
  const rustTriples = new Set<string>();
  for (const entry of dump.entries) {
    const key = `${entry.scope}\0${entry.export}\0${entry.format}`;
    rustTriples.add(key);
    if (!known.has(entry.format)) diagnostics.push({ code: "rust-entry-format-unknown", path, detail: `${entry.scope}/${entry.export} registers format ${JSON.stringify(entry.format)}; the declared ids are ${[...known].sort().join(", ")}.` });
    else if (!catalog.scopes[entry.scope]) diagnostics.push({ code: "rust-scope-unknown", path, detail: `The registry declares scope ${entry.scope}, which the catalog does not contain.` });
    else if (!Object.hasOwn(catalog.scopes[entry.scope]!.exports, entry.export)) diagnostics.push({ code: "rust-export-unknown", path, detail: `The registry declares ${entry.scope}/${entry.export}, which ${catalog.scopes[entry.scope]!.path} does not export.` });
    else if (!catalogTriples.has(key)) diagnostics.push({ code: "rust-entry-format-absent", path, detail: `The registry resolves ${entry.scope}/${entry.export} in ${entry.format}; ${catalog.scopes[entry.scope]!.path} declares no leaf for that format.` });
  }
  for (const key of [...catalogTriples].sort(byteSort)) {
    if (rustTriples.has(key)) continue;
    const [scopeId, exportId, format] = key.split("\0") as [string, string, string];
    diagnostics.push({ code: "rust-entry-missing", path, detail: `The catalog declares ${scopeId}/${exportId} in ${format}; the registry of that scope does not register it.` });
  }
  if (complete) for (const scopeId of Object.keys(catalog.scopes).sort(byteSort)) {
    if (declared.has(scopeId)) continue;
    diagnostics.push({ code: "rust-scope-unregistered", path, detail: `${catalog.scopes[scopeId]!.path} declares scope ${scopeId}; no register_scope_schema_exports call publishes it.` });
  }
  return diagnostics.slice().sort((left, right) => byteSort(left.code, right.code) || byteSort(left.detail, right.detail));
}

/** 🧾️ One JSON line per finding, byte-stable across runs, for `schema check --report`. */
export function renderSchemaCheckReport(findings: readonly SchemaScopeDiagnostic[]): string {
  return findings.map((finding) => JSON.stringify(finding)).join("\n") + (findings.length > 0 ? "\n" : "");
}
//#endregion 🧬️SchemaScopeCatalog

/** 📦️ Allowed semantic directory kinds inside one language package. */
export function packagingDirectoryKindIdsForLang(lang: string, taxonomy: Taxonomy = loadTaxonomy()): readonly string[] {
  const global = taxonomy.packagingDirectoryKindIds ?? [];
  const ecosystem = taxonomy.ecosystems[lang]?.packagingDirectoryKindIds ?? [];
  return [...new Set([...global, ...ecosystem])];
}

/** 🌳️ Level descriptor: fixed allowlist or wildcard (`*` = any emoji-prefixed slug dir). */
type ArtifactFacetLevel =
  | { readonly kind: "fixed"; readonly dirs: readonly string[] }
  | { readonly kind: "wildcard" }
  | { readonly kind: "none" };

/**
 * 🂡 Whether a dir name is an emoji-prefixed slug — an Extended_Pictographic codepoint at the
 * start with the canonical selector and resolve to exactly one semantic-directory registry entry.
 */
function isEmojiPrefixedSlugDir(name: string, taxonomy: Taxonomy): boolean {
  return semanticDirectoryKindId(name, taxonomy) !== null;
}

/** 🏘️ Validates explicitly authored two-tier mutation owners without assigning names or traversing files. */
export function mutationDomainOwnersProblems(owners: Taxonomy["mutationDomainOwners"], genericEmojiIdentities: readonly string[] = []): string[] {
  const problems: string[] = [];
  if (!owners || typeof owners !== "object" || Array.isArray(owners)) return ["mutationDomainOwners must be an exact-owner object."];
  for (const [root, domains] of Object.entries(owners)) {
    if (!root.endsWith("/🧬️mutations") || root !== root.normalize("NFC") || /[*?{}]/u.test(root) || root.includes(String.fromCharCode(92)) || [...root].some((character) => character.charCodeAt(0) < 32) || root.split("/").some((part) => !part || part === "." || part === "..")) problems.push(`mutationDomainOwners[${JSON.stringify(root)}] must name one exact repository mutation root.`);
    if (!domains || typeof domains !== "object" || Array.isArray(domains) || Object.keys(domains).length === 0) {
      problems.push(`mutationDomainOwners[${JSON.stringify(root)}] must declare non-empty domains.`);
      continue;
    }
    const identities = new Set<string>();
    const entries: { path: string; nodeKind: "directory" }[] = [];
    for (const [domain, operations] of Object.entries(domains)) {
      const domainId = leadingEmojiIdentity(domain).rest;
      entries.push({ path: `${root}/${domain}`, nodeKind: "directory" });
      if (domain.includes("/") || domain.includes(String.fromCharCode(92)) || !/^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/u.test(domainId)) problems.push(`${root}/${domain} is not one domain basename.`);
      if (!operations || typeof operations !== "object" || Array.isArray(operations) || Object.keys(operations).length === 0) {
        problems.push(`${root}/${domain} must declare non-empty operations.`);
        continue;
      }
      for (const [operation, identity] of Object.entries(operations)) {
        const operationId = leadingEmojiIdentity(operation).rest;
        entries.push({ path: `${root}/${domain}/${operation}`, nodeKind: "directory" });
        if (operation.includes("/") || operation.includes(String.fromCharCode(92)) || !/^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/u.test(operationId) || typeof identity !== "string" || !/^[a-z][a-z0-9]*(?:-[a-z0-9]+)+$/u.test(identity)) problems.push(`${root}/${domain}/${operation} must declare one operation basename and its explicit full semantic identity.`);
        if (identities.has(identity)) problems.push(`${root} has duplicate semantic identity ${JSON.stringify(identity)}.`);
        identities.add(identity);
      }
    }
    for (const finding of pathEmojiStatuteFindings(entries, genericEmojiIdentities)) problems.push(`${finding.path} violates mutation-domain ${finding.kind} emoji identity.`);
  }
  return problems;
}

/** 🛂️ Validates direct source ownership without cross-artifact, cross-standard, chained, or inferred ownership. */
export function mutationCatalogSourceOwnersProblems(taxonomy: Pick<Taxonomy, "mutationCatalogSourceOwners" | "mutationDomainOwners">): string[] {
  const owners = taxonomy.mutationCatalogSourceOwners, problems: string[] = [];
  if (!owners || typeof owners !== "object" || Array.isArray(owners)) return ["mutationCatalogSourceOwners must be an exact-owner object."];
  const profile = (path: unknown): RegExpMatchArray | null => typeof path === "string" && path === path.normalize("NFC") && !/[\\\\:*?{}\u0000-\u001F]/u.test(path) && path.split("/").every((part) => part && part !== "." && part !== "..") ? path.match(/^(.+)\/🏅️standards\/(🔖️[^/]+)\/🪆️subsets\/([^/]+)$/u) : null;
  for (const [owner, source] of Object.entries(owners)) {
    const catalogProfile = profile(owner), sourceProfile = profile(source);
    if (!catalogProfile || !sourceProfile || catalogProfile[1] !== sourceProfile[1] || catalogProfile[2] !== sourceProfile[2] || owner === source || Object.hasOwn(owners, source) || !Object.hasOwn(taxonomy.mutationDomainOwners, `${source}/🧬️schema/🧬️mutations`)) problems.push(`mutationCatalogSourceOwners[${JSON.stringify(owner)}] must reference one distinct registered source subset in the same artifact and standard without ownership chains.`);
  }
  return problems;
}

/** 🧭️ Resolves only an exact declared catalog source; unmapped owners retain their own current source tree. */
export function mutationCatalogSourceOwner(owner: string, taxonomy: Pick<Taxonomy, "mutationCatalogSourceOwners" | "mutationDomainOwners"> = loadTaxonomy()): string | null {
  if (!Object.hasOwn(taxonomy.mutationCatalogSourceOwners, owner)) return owner;
  return mutationCatalogSourceOwnersProblems(taxonomy).length === 0 ? taxonomy.mutationCatalogSourceOwners[owner]! : null;
}

/** 🪪️ Resolves a physical mutation owner only through its declared exact layout. */
export function mutationOwnerIdentity(root: string, ownerPath: string, taxonomy: Taxonomy = loadTaxonomy()): string | null {
  if (ownerPath !== ownerPath.normalize("NFC") || ownerPath.includes(String.fromCharCode(92))) return null;
  const domains = taxonomy.mutationDomainOwners[root];
  if (domains) {
    const [domain, operation, extra] = ownerPath.split("/");
    return extra === undefined && domain && operation && Object.hasOwn(domains, domain) && Object.hasOwn(domains[domain]!, operation) ? domains[domain]![operation]! : null;
  }
  return !ownerPath.includes("/") && mutationDirectoryNameIsValid(ownerPath, taxonomy) ? ownerPath.match(/[a-z][a-z0-9]*(?:-[a-z0-9]+)+$/u)?.[0] ?? null : null;
}

/** 🗺️ Resolves one semantic ID to its explicitly registered domain and operation path. */
export function mutationOwnerRelativePath(root: string, identity: string, taxonomy: Pick<Taxonomy, "mutationDomainOwners"> = loadTaxonomy()): string | null {
  const paths = Object.entries(taxonomy.mutationDomainOwners[root] ?? {}).flatMap(([domain, operations]) => Object.entries(operations).filter(([, value]) => value === identity).map(([operation]) => `${domain}/${operation}`));
  return paths.length === 1 ? paths[0]! : null;
}

/** 🧬️ Whether one direct mutation owner has the configured emoji + semantic verb-noun identity. */
export function mutationDirectoryNameIsValid(name: string, taxonomy: Taxonomy = loadTaxonomy()): boolean {
  return name === name.normalize("NFC") && new RegExp(taxonomy.mutationDirectoryPattern, "u").test(name);
}

/** 🏗️ Free top-level `fn <name>(` declarations (Rust's structural shape for an extracted diff/inverse body) keyed by the behavior facet they belong to. A trait-impl method (`async fn diff(&self, ...) { diff(self, base) }`, indented inside `impl … {}`) never matches — only a column-zero free function does, which is exactly the shape the collapsed leaves reduce to once split-out logic gets folded back in. */
const MUTATION_DIRECT_LEAF_STRUCTURAL_PATTERNS: Readonly<Record<string, RegExp>> = {
  "🔺️diff": /^pub (?:async )?fn diff\(/mu,
  "↩️inverse": /^pub (?:async )?fn inverse\(/mu,
};

/**
 * 🔖️🏗️ Behavior facets (`🔺️diff`/`↩️inverse`) that a mutation's direct leaf re-inlines instead of placing
 * in their own facet directory — the exact regression the SEMANTIC-MUTATIONS-OVERHAUL contract forbids.
 *
 * STRUCTURAL detection is the actual contract: a free `pub (async)? fn diff(`/`fn inverse(` in the direct
 * leaf with no sibling facet directory present is a violation regardless of comments — an author who
 * simply omits a `//#region` marker cannot evade this (confirmed at 266-mutation scale in `🏛️architect`,
 * where every leaf was marker-free). `siblingFacetDirs` must be the actual child directory names observed
 * beside the direct leaf on disk; pass an empty set only when no sibling facets exist (e.g. an inline fixture).
 *
 * The `mutationDirectLeafForbiddenRegionMarkers` marker scan still runs, unioned in: it is the only signal
 * for a non-Rust direct leaf (e.g. a `🟦️.ts` mirror, where "free `pub fn diff(`" has no meaning) and for any
 * Rust shape that carries the marker without matching the bare free-function form. It adds coverage the
 * structural check cannot reach; it is not a substitute for it.
 *
 * Empty means the direct leaf is clean.
 */
export function mutationDirectLeafInlinedBehaviorFacets(directLeafSource: string, siblingFacetDirs: ReadonlySet<string> = new Set(), taxonomy: Taxonomy = loadTaxonomy()): readonly string[] {
  const found = new Set<string>();
  const markers = taxonomy.mutationDirectLeafForbiddenRegionMarkers ?? {};
  for (const [facet, marker] of Object.entries(markers)) {
    if (new RegExp(`//#region\\s+${marker.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&")}\\b`, "u").test(directLeafSource)) found.add(facet);
  }
  for (const [facet, pattern] of Object.entries(MUTATION_DIRECT_LEAF_STRUCTURAL_PATTERNS)) {
    if (pattern.test(directLeafSource) && !siblingFacetDirs.has(facet)) found.add(facet);
  }
  return [...found].sort();
}

/** 🌳️ Declared child level of a path under an artifact root (parents are `/`-segments already accepted). */
function artifactFacetChildLevel(parents: readonly string[], taxonomy: Taxonomy): ArtifactFacetLevel {
  if (parents.length === 0) return { kind: "fixed", dirs: taxonomy.artifactComponentDirs };
  const root = parents[0]!;
  const a = parents[1];
  const b = parents[2];
  const c = parents[3];
  if (parents.length === 1) {
    if (root === "🧬️schema") return { kind: "fixed", dirs: taxonomy.schemaChildDirs ?? [] };
    if (root === "🚪️io") return { kind: "fixed", dirs: [...(taxonomy.ioDirectionDirs ?? []), ...(taxonomy.representationDirs ?? [])] };
    return { kind: "none" };
  }
  if (root === "🧬️schema") {
    if (parents.length === 2 && (taxonomy.schemaChildDirs ?? []).includes(a!)) {
      if (a === "🧬️mutations") return { kind: "fixed", dirs: ["*"] };
      if (a === "💡️inferences") return { kind: "fixed", dirs: ["*"] };
      return { kind: "none" };
    }
    if (parents.length === 3 && a === "🧬️mutations") {
      if ((taxonomy.representationDirs ?? []).includes(b!)) return { kind: "none" };
      return { kind: "fixed", dirs: [...(taxonomy.mutationBehaviorFacetDirs ?? []), ...(taxonomy.mutationOrganizationalFacetDirs ?? [])] };
    }
    if (parents.length === 3 && a === "💡️inferences") return { kind: "none" };
    if (parents.length === 3 && (taxonomy.representationDirs ?? []).includes(b!)) return { kind: "none" };
    if (parents.length === 4 && a === "🧬️mutations") return { kind: "none" };
    return { kind: "none" };
  }
  if (root === "🚪️io") {
    const directions = taxonomy.ioDirectionDirs ?? [];
    const childMap = taxonomy.ioDirectionChildDirs ?? {};
    if (parents.length === 2 && (taxonomy.representationDirs ?? []).includes(a!)) return { kind: "fixed", dirs: taxonomy.ioSemanticCollectionDirNames ?? [] };
    if (parents.length === 3 && (taxonomy.representationDirs ?? []).includes(a!) && (taxonomy.ioSemanticCollectionDirNames ?? []).includes(b!)) return { kind: b === "🧬️mutations" || b === "💡️inferences" ? "wildcard" : "none" };
    if (parents.length === 4 && (taxonomy.representationDirs ?? []).includes(a!) && (b === "🧬️mutations" || b === "💡️inferences")) return { kind: "none" };
    if (parents.length === 2 && directions.includes(a!)) {
      const child = childMap[a!];
      return child ? { kind: "fixed", dirs: [child] } : { kind: "none" };
    }
    if (parents.length === 3 && directions.includes(a!) && childMap[a!] === b) {
      return { kind: "fixed", dirs: [taxonomy.artifactsDirName] };
    }
    if (parents.length === 4 && b === childMap[a!] && c === taxonomy.artifactsDirName) return { kind: "wildcard" };
    if (parents.length === 5) return { kind: "none" };
    return { kind: "none" };
  }
  return { kind: "none" };
}

/** 🌳️ Declared children of a nesting artifact facet path (`/`-joined parents), empty when leaves-only. */
function artifactFacetChildDirs(facetPath: string, taxonomy: Taxonomy): readonly string[] {
  const parents = facetPath ? facetPath.split("/") : [];
  const level = artifactFacetChildLevel(parents, taxonomy);
  if (level.kind !== "fixed") return [];
  return level.dirs.filter((d) => d !== "*");
}

/** 🧭️ Whether a `/`-joined facet path walks only declared dirs from an artifact root (supports `*` wildcard levels). */
export function artifactFacetPathIsDeclared(facetPath: string, taxonomy: Taxonomy = loadTaxonomy()): boolean {
  const [root, ...rest] = facetPath.split("/");
  if (!root || !taxonomy.artifactComponentDirs.includes(root)) return false;
  const parents: string[] = [root];
  for (const segment of rest) {
    if ((parents[0] === "🧬️schema" || parents[0] === "🚪️io" && parents.length >= 3) && (taxonomy.representationDirs ?? []).includes(segment)) return false;
    const level = artifactFacetChildLevel(parents, taxonomy);
    if (level.kind === "none") return false;
    const directMutationOwner = parents.length === 2 && parents[0] === "🧬️schema" && parents[1] === "🧬️mutations" || parents.length === 3 && parents[0] === "🚪️io" && parents[2] === "🧬️mutations";
    const directInferenceOwner = parents.length === 2 && parents[0] === "🧬️schema" && parents[1] === "💡️inferences" || parents.length === 3 && parents[0] === "🚪️io" && parents[2] === "💡️inferences";
    const wildcardAccepted = directMutationOwner ? mutationDirectoryNameIsValid(segment, taxonomy) : directInferenceOwner ? semanticDirectoryKindId(segment, taxonomy, { parentKindId: "inferences" }) !== null : parents.at(-1) === taxonomy.artifactsDirName ? semanticDirectoryKindId(segment, taxonomy, { parentKindId: "artifacts" }) !== null : isEmojiPrefixedSlugDir(segment, taxonomy);
    if (level.kind === "wildcard") {
      if (!wildcardAccepted) return false;
    } else {
      const dirs = level.dirs;
      const allowWildcard = dirs.includes("*");
      const fixed = dirs.filter((d) => d !== "*");
      if (!(fixed.includes(segment) || (allowWildcard && wildcardAccepted))) return false;
    }
    parents.push(segment);
  }
  return true;
}

/** 🚧️ The only opaque subtrees the taxonomy admits, in their declared order: two user-owned
 * scratch trees, and the one tracked nested-repository gitlink (`git ls-files -s` mode `160000`),
 * which must be filtered lexically before source admission or `inventoryTaxonomyWithSourceParentPruning`
 * refuses to classify anything at all. Every entry here is a whole opaque subtree, so nothing the
 * repository generates may live under one — which is why the gitlink itself is named, not its parent
 * `♻️mit-bestand/`, whose `📋️bericht`/`🖼️asset` subtrees are generator-contract outputs. */
