      }
      const token: TypeScriptDeclarationToken = { kind, text, value, start, end: this.cursor, lineBreakBefore: /[\r\n\u2028\u2029]/u.test(this.source.slice(previousEnd, start)), ...(interpolated === undefined ? {} : { interpolated }) };
